INSERT INTO `categories` VALUES (502,'Tổng quan','Overview','','','Tổng quan','Overview','<h2>Hiện diện từ Bắc v&agrave;o Nam</h2>\r\n<p>Th&agrave;nh lập ng&agrave;y 20/03/2018 tại phố Nguyễn Văn Cừ, H&agrave; Nội, AMS đ&atilde; lần lượt đưa v&agrave;o vận h&agrave;nh kho h&oacute;a chất 10.000 m&sup2; tại Hưng Y&ecirc;n (2020), kho ngoại quan tại Hải Ph&ograve;ng (2022) phục vụ doanh nghiệp chế xuất, v&agrave; văn ph&ograve;ng tại TP. Hồ Ch&iacute; Minh (2024) để hỗ trợ kh&aacute;ch h&agrave;ng khu vực ph&iacute;a Nam.</p>\r\n<p>Năm 2019, AMS trở th&agrave;nh nh&agrave; ph&acirc;n phối của Shin-Etsu Silicones tại Việt Nam với cam kết d&agrave;i hạn về chuỗi cung ứng; năm 2021, AMS được cấp giấy ph&eacute;p kinh doanh h&oacute;a chất &ndash; bước tiến quan trọng để trở th&agrave;nh nh&agrave; ph&acirc;n phối h&oacute;a chất tr&ecirc;n thị trường Việt Nam.</p>\r\n<p><img src=\"uploads/images/ams/gt-earth.jpg\" alt=\"Mạng lưới AMS\" width=\"500\" height=\"500\" loading=\"lazy\"></p>\r\n<h2>AMS qua những con số</h2>\r\n<p><img src=\"uploads/images/ams/gt-chart.jpg\" alt=\"AMS qua những con số\" width=\"640\" height=\"426\" loading=\"lazy\"></p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<th>T&ecirc;n c&ocirc;ng ty</th>\r\n<td>C&ocirc;ng ty TNHH AMS Việt Nam</td>\r\n</tr>\r\n<tr>\r\n<th>Trụ sở</th>\r\n<td>Số 19A, ng&aacute;ch 57, ng&otilde; 640 Nguyễn Văn Cừ, P. Gia Thụy, Q. Long Bi&ecirc;n, H&agrave; Nội</td>\r\n</tr>\r\n<tr>\r\n<th>Năm th&agrave;nh lập</th>\r\n<td>20/03/2018</td>\r\n</tr>\r\n<tr>\r\n<th>Doanh thu</th>\r\n<td>25.000.000.000 VNĐ (t&iacute;nh đến 12/2024)</td>\r\n</tr>\r\n<tr>\r\n<th>Nh&acirc;n sự</th>\r\n<td>15 người (07/2024)</td>\r\n</tr>\r\n<tr>\r\n<th>Vốn điều lệ</th>\r\n<td>10.000.000.000 VNĐ</td>\r\n</tr>\r\n<tr>\r\n<th>Ng&acirc;n h&agrave;ng</th>\r\n<td>Ng&acirc;n h&agrave;ng TMCP Ngoại thương Việt Nam (Vietcombank)</td>\r\n</tr>\r\n</tbody>\r\n</table>','<p>The overview of AMS is being updated. Please contact the AMS hotline 039.89.89.333 for detailed advice.</p>',1002,501,'','',NULL,NULL,2,3,'','','','','','',0,0,1,0,0,0,'page',0,0,0,0,1,'',NULL,NULL,NULL,1),(503,'Nguyên tắc','Principles',NULL,NULL,'Nguyên tắc','Principles','<h2>Nguyên tắc hoạt động</h2><p>Chúng tôi tạo ra giá trị mới thông qua việc thực hành “các nguyên tắc chung về chất lượng quản trị AMS”, cung cấp cho khách hàng thông tin, vật liệu, sản phẩm, công nghệ và dịch vụ phù hợp nhất để nâng cao độ tin cậy, sự hài lòng và cùng kiến tạo một tương lai thịnh vượng.</p><p>AMS Việt Nam hướng tới chất lượng quản trị đẳng cấp thế giới. Mỗi nhân viên cam kết tuân thủ nghiêm túc các quy định về chất lượng công việc, luôn mở rộng tầm nhìn và nỗ lực không ngừng mỗi ngày.</p><h2>Triết lý &amp; sứ mệnh</h2><p>AMS tạo ra giá trị thực bằng cách mang lại sự hài lòng tối đa cho khách hàng với vai trò nhà cung cấp giải pháp vật liệu toàn diện, cân nhắc kỹ lưỡng chất lượng sản phẩm, chi phí và môi trường. Sứ mệnh của chúng tôi là tạo ra giá trị tuyệt đối và thực hiện trách nhiệm xã hội của doanh nghiệp, mang lại giá trị tốt nhất cho người dùng cuối và không ngừng đổi mới chính mình.</p>','<p>The principles of AMS is being updated. Please contact the AMS hotline 039.89.89.333 for detailed advice.</p>',1003,501,NULL,NULL,NULL,NULL,4,5,NULL,NULL,NULL,NULL,NULL,NULL,0,0,1,0,0,0,'page',0,0,0,0,1,'',NULL,NULL,NULL,1),(504,'Giá trị cốt lõi','Core values',NULL,NULL,'Giá trị cốt lõi','Core values','<h2>Chiến lược nền tảng</h2><ol><li>Tăng cường các mảng kinh doanh giá trị gia tăng cao – mở rộng kinh doanh mô-đun và ODM.</li><li>Phát triển khách hàng hàng đầu trong và ngoài nước, đặc biệt các khách hàng lớn từ Mỹ và châu Âu.</li><li>Tập trung vào lĩnh vực ô tô, mở rộng danh mục theo xu hướng điện hóa.</li><li>Khai phá các khu vực tiềm năng, phát triển khách hàng và nhà cung cấp tại ASEAN.</li><li>Tăng cường bộ phận Marketing &amp; Phát triển, xây dựng đội chuyên trách hợp tác với tập đoàn Shin-Etsu Silicone.</li></ol><h2>Hình ảnh AMS</h2>','<p>The core values of AMS is being updated. Please contact the AMS hotline 039.89.89.333 for detailed advice.</p>',1004,501,NULL,NULL,NULL,NULL,6,7,NULL,NULL,NULL,NULL,NULL,NULL,0,0,1,0,0,0,'page',0,0,0,0,1,'',NULL,NULL,NULL,1),(505,'Tầm nhìn sứ mệnh','Vision & mission',NULL,NULL,'Tầm nhìn sứ mệnh','Vision & mission','<h2>Tầm nhìn</h2><p>Ngành điện tử thay đổi từng ngày. AMS cần phản ứng linh hoạt trước biến động nhu cầu và mang lại giá trị gia tăng khi nhu cầu khách hàng ngày càng tinh vi, đa dạng. Chúng tôi theo đuổi quản trị bền vững, phát triển kinh doanh gắn với các vấn đề môi trường và xã hội.</p><p>Bằng cách tích hợp chiến lược năng lực tại chỗ lâu năm cùng năm chức năng cốt lõi, AMS cung cấp sản phẩm và dịch vụ giá trị gia tăng cao, chinh phục khách hàng hàng đầu trong và ngoài nước cùng các thị trường tiềm năng trung và dài hạn.</p>','<p>The vision & mission of AMS is being updated. Please contact the AMS hotline 039.89.89.333 for detailed advice.</p>',1005,501,NULL,NULL,NULL,NULL,8,9,NULL,NULL,NULL,NULL,NULL,NULL,0,0,1,0,0,0,'page',0,0,0,0,1,'',NULL,NULL,NULL,1),(501,'Giới thiệu','About us',NULL,NULL,'Giới thiệu','About us','<h2>Nhà phân phối vật liệu công nghệ cao cho ngành sản xuất</h2><p>AMS Việt Nam được chính thức thành lập trên nền tảng niềm tin và sự hợp tác bền vững giữa các đối tác và khách hàng. Theo thời gian, chúng tôi đã xây dựng mạng lưới phân phối các sản phẩm công nghệ cao từ nhiều quốc gia như Nhật Bản, Đức, Hàn Quốc, Trung Quốc, Thái Lan, Malaysia… đến thị trường Việt Nam.</p><p>Hiện nay AMS tập trung cung cấp vật liệu cho ngành công nghiệp sản xuất:</p><ul><li>Silicone Shin-Etsu</li><li>Vật liệu điện tử</li><li>Nhựa &amp; hạt nhựa</li><li>Mỡ &amp; dầu bôi trơn</li><li>Dụng cụ chính xác</li><li>Hóa chất, phụ kiện dây &amp; cáp điện và các sản phẩm tiêu hao khác</li></ul><h2>Vì sao chọn AMS</h2><p>AMS – Advanced Materials Solution – mang đến giải pháp vật liệu tiên tiến cho các ngành điện tử, ô tô, nhựa và nhiều ngành công nghiệp khác. Chúng tôi luôn tiếp nhận những ý tưởng mới, công nghệ mới để nâng cao chất lượng dịch vụ, đồng hành cùng khách hàng từ khâu lựa chọn vật liệu đến khi đưa vào sản xuất hàng loạt.</p>','<p>AMS (Advance Material Solution) has over 15 years of experience in industrial materials and solutions, working with leading brands to deliver tailor-made solutions that cut costs for factories without compromising quality.</p>',1001,NULL,NULL,'uploads/images/ams/gt-banner.jpg',NULL,NULL,1,10,NULL,NULL,NULL,NULL,NULL,NULL,1,0,0,0,0,0,'page',0,0,0,0,1,'gioi-thieu',NULL,NULL,NULL,1),(507,'Xe hơi','Automotive','AMS đồng hành cùng các nhà sản xuất linh kiện ô tô trong toàn bộ quy trình: từ lựa chọn vật liệu kết dính, cách âm, chống rung đến hỗ trợ kỹ thuật trên dây chuyền lắp ráp nội thất và điện tử xe.','AMS supports automotive component manufacturers throughout the entire process: from selecting bonding, sound-insulation and anti-vibration materials to technical support on interior and vehicle electronics assembly lines.','Xe hơi','Automotive','<p>AMS đồng hành cùng các nhà sản xuất linh kiện ô tô trong toàn bộ quy trình: từ lựa chọn vật liệu kết dính, cách âm, chống rung đến hỗ trợ kỹ thuật trên dây chuyền lắp ráp nội thất và điện tử xe.</p>','<p>AMS supports automotive component manufacturers throughout the entire process: from selecting bonding, sound-insulation and anti-vibration materials to technical support on interior and vehicle electronics assembly lines.</p>',1007,506,NULL,'uploads/images/ams/cat-1.jpg',NULL,NULL,13,14,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,1,0,0,'product',0,0,0,1,1,'',NULL,NULL,NULL,1),(508,'Loa & Tai nghe','Audio devices','Vật liệu dán màng loa, đệm tiêu âm và băng keo dẫn điện giúp các nhà máy âm thanh nâng cao độ bền sản phẩm, giảm tỷ lệ lỗi trên dây chuyền và tối ưu chi phí lắp ráp.','Speaker membrane adhesives, acoustic pads and conductive tapes help audio factories improve product durability, reduce defect rates on the line and optimize assembly costs.','Loa & Tai nghe','Audio devices','<p>Vật liệu dán màng loa, đệm tiêu âm và băng keo dẫn điện giúp các nhà máy âm thanh nâng cao độ bền sản phẩm, giảm tỷ lệ lỗi trên dây chuyền và tối ưu chi phí lắp ráp.</p>','<p>Speaker membrane adhesives, acoustic pads and conductive tapes help audio factories improve product durability, reduce defect rates on the line and optimize assembly costs.</p>',1008,506,NULL,'uploads/images/ams/cat-2.jpg',NULL,NULL,15,16,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,1,0,0,'product',0,0,0,1,1,'',NULL,NULL,NULL,1),(509,'Mô-đun máy ảnh','Camera modules','Giải pháp băng keo siêu mỏng, vật liệu che sáng và chống bụi cho cụm mô-đun máy ảnh, đáp ứng dung sai lắp ráp khắt khe của các dòng thiết bị di động thế hệ mới.','Ultra-thin tapes, light-shielding and dust-proof materials for camera module assemblies, meeting the tight assembly tolerances of next-generation mobile devices.','Mô-đun máy ảnh','Camera modules','<p>Giải pháp băng keo siêu mỏng, vật liệu che sáng và chống bụi cho cụm mô-đun máy ảnh, đáp ứng dung sai lắp ráp khắt khe của các dòng thiết bị di động thế hệ mới.</p>','<p>Ultra-thin tapes, light-shielding and dust-proof materials for camera module assemblies, meeting the tight assembly tolerances of next-generation mobile devices.</p>',1009,506,NULL,'uploads/images/ams/cat-3.jpg',NULL,NULL,17,18,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,1,0,0,'product',0,0,0,1,1,'',NULL,NULL,NULL,1),(510,'Chất bán dẫn','Semiconductors','Vật liệu tản nhiệt, băng keo chịu nhiệt và vật tư phòng sạch cho quy trình đóng gói, kiểm thử chip bán dẫn với tiêu chuẩn chất lượng quốc tế.','Thermal materials, heat-resistant tapes and cleanroom supplies for semiconductor packaging and testing processes to international quality standards.','Chất bán dẫn','Semiconductors','<p>Vật liệu tản nhiệt, băng keo chịu nhiệt và vật tư phòng sạch cho quy trình đóng gói, kiểm thử chip bán dẫn với tiêu chuẩn chất lượng quốc tế.</p>','<p>Thermal materials, heat-resistant tapes and cleanroom supplies for semiconductor packaging and testing processes to international quality standards.</p>',1010,506,NULL,'uploads/images/ams/cat-4.jpg',NULL,NULL,19,20,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,0,0,0,'product',0,0,0,1,1,'',NULL,NULL,NULL,1),(511,'Ngành điện tử','Electronics','Cung cấp vật liệu cách điện, chống tĩnh điện và lớp phủ bảo vệ bo mạch, giúp sản phẩm điện tử vận hành ổn định trong môi trường khắc nghiệt.','Insulation, anti-static materials and PCB protective coatings that keep electronic products running reliably in harsh environments.','Ngành điện tử','Electronics','<p>Cung cấp vật liệu cách điện, chống tĩnh điện và lớp phủ bảo vệ bo mạch, giúp sản phẩm điện tử vận hành ổn định trong môi trường khắc nghiệt.</p>','<p>Insulation, anti-static materials and PCB protective coatings that keep electronic products running reliably in harsh environments.</p>',1011,506,NULL,'uploads/images/ams/cat-5.jpg',NULL,NULL,21,22,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,0,0,0,'product',0,0,0,1,1,'',NULL,NULL,NULL,1),(512,'Thiết bị y tế','Medical devices','Băng keo y tế, vật liệu tương thích sinh học và mút xốp kỹ thuật cho thiết bị chẩn đoán, đáp ứng yêu cầu an toàn và truy xuất nguồn gốc của ngành y tế.','Medical tapes, biocompatible materials and technical foams for diagnostic devices, meeting the safety and traceability requirements of the medical industry.','Thiết bị y tế','Medical devices','<p>Băng keo y tế, vật liệu tương thích sinh học và mút xốp kỹ thuật cho thiết bị chẩn đoán, đáp ứng yêu cầu an toàn và truy xuất nguồn gốc của ngành y tế.</p>','<p>Medical tapes, biocompatible materials and technical foams for diagnostic devices, meeting the safety and traceability requirements of the medical industry.</p>',1012,506,NULL,'uploads/images/ams/cat-4.jpg',NULL,NULL,23,24,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,0,0,0,'product',0,0,0,1,1,'',NULL,NULL,NULL,1),(513,'Pin & Năng lượng','Batteries & Energy','Vật liệu cách nhiệt, chống cháy lan và băng keo cố định cell pin cho các nhà máy sản xuất pin và hệ thống lưu trữ năng lượng.','Thermal insulation, flame-retardant materials and cell-fixing tapes for battery factories and energy storage systems.','Pin & Năng lượng','Batteries & Energy','<p>Vật liệu cách nhiệt, chống cháy lan và băng keo cố định cell pin cho các nhà máy sản xuất pin và hệ thống lưu trữ năng lượng.</p>','<p>Thermal insulation, flame-retardant materials and cell-fixing tapes for battery factories and energy storage systems.</p>',1013,506,NULL,'uploads/images/ams/cat-2.jpg',NULL,NULL,25,26,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,0,0,0,'product',0,0,0,0,1,'',NULL,NULL,NULL,1),(514,'Xây dựng','Construction','Băng keo kết cấu, vật liệu chống thấm và gioăng làm kín cho công trình công nghiệp và dân dụng, bền bỉ với thời tiết khắc nghiệt.','Structural tapes, waterproofing materials and sealing gaskets for industrial and residential projects, durable in harsh weather.','Xây dựng','Construction','<p>Băng keo kết cấu, vật liệu chống thấm và gioăng làm kín cho công trình công nghiệp và dân dụng, bền bỉ với thời tiết khắc nghiệt.</p>','<p>Structural tapes, waterproofing materials and sealing gaskets for industrial and residential projects, durable in harsh weather.</p>',1014,506,NULL,'uploads/images/ams/cat-3.jpg',NULL,NULL,27,28,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,1,0,0,'product',0,0,0,0,1,'',NULL,NULL,NULL,1),(506,'Ngành nghề','Industries',NULL,NULL,'Ngành nghề','Industries',NULL,NULL,1006,515,NULL,NULL,NULL,NULL,12,29,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,0,0,0,'product',0,0,0,0,1,'',NULL,NULL,NULL,1),(516,'Băng keo','Adhesive tapes',NULL,NULL,'Băng keo','Adhesive tapes',NULL,NULL,1016,530,NULL,'uploads/images/ams/cat-1.jpg',NULL,NULL,41,42,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,0,0,0,'product',0,0,1,0,1,'',NULL,NULL,NULL,1),(519,'Mút xốp & Chống rung','Foam & Anti Vibration',NULL,NULL,'Mút xốp & Chống rung','Foam & Anti Vibration',NULL,NULL,1019,530,NULL,'uploads/images/ams/cat-4.jpg',NULL,NULL,43,44,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,0,0,0,'product',0,0,1,0,1,'',NULL,NULL,NULL,1),(520,'Phủ bảo vệ','Conformal Coating',NULL,NULL,'Phủ bảo vệ','Conformal Coating',NULL,NULL,1020,530,NULL,'uploads/images/ams/cat-5.jpg',NULL,NULL,39,40,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,0,0,0,'product',0,0,1,0,1,'',NULL,NULL,NULL,1),(515,'Sản phẩm','Products','<p>AMS là nhà phân phối chính thức của <a href=\"theo-thuong-hieu.html\">Shin-Etsu Silicones</a> tại Việt Nam từ năm 2019, cùng hơn 40 thương hiệu vật liệu hàng đầu: băng keo công nghiệp, vật liệu tản nhiệt, cách điện, mút xốp chống rung và lớp phủ bảo vệ. Vật liệu có độ bền nhiệt, cách điện, chống thấm và ổn định hóa học vượt trội, được dùng rộng rãi trong ngành điện tử, ô tô, nhựa và xây dựng. Đội ngũ kỹ thuật AMS hỗ trợ lựa chọn mã sản phẩm phù hợp, cung cấp mẫu thử và tài liệu kỹ thuật (TDS, SDS) cho từng ứng dụng cụ thể.</p>',NULL,'Sản phẩm','Products',NULL,NULL,1015,NULL,NULL,'uploads/images/ams/hero.jpg',NULL,NULL,11,46,NULL,NULL,NULL,NULL,NULL,NULL,1,1,0,0,0,0,'product',0,0,0,0,1,'',NULL,NULL,NULL,1),(521,'Tin tức','News',NULL,NULL,'Tin tức','News',NULL,NULL,1021,NULL,NULL,'uploads/images/ams/tt-banner.jpg',NULL,NULL,59,60,NULL,NULL,NULL,NULL,NULL,NULL,1,0,0,0,0,0,'news',0,0,0,0,1,'',NULL,NULL,NULL,1),(522,'Sự kiện','Events',NULL,NULL,'Sự kiện','Events',NULL,NULL,1022,NULL,NULL,'uploads/images/ams/tt-banner.jpg',NULL,NULL,61,62,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,'news',0,0,0,0,1,'',NULL,NULL,NULL,1),(523,'Theo thương hiệu','By brand','<p>AMS là nhà phân phối hơn 40 nhà sản xuất hàng đầu trong ngành về keo dán hiệu năng cao, chất trám kín, lớp phủ bảo vệ, vật liệu đổ khuôn, thiết bị định lượng, hóa chất chuyên dụng và thiết bị đóng rắn UV – tất cả từ một đầu mối. Khám phá các thương hiệu AMS đang đồng hành dưới đây.</p>',NULL,'Theo thương hiệu','By brand','<p>Theo thương hiệu của AMS đang được cập nhật. Vui lòng liên hệ hotline 039.89.89.333 để được tư vấn chi tiết.</p>','<p>The by-brand section of AMS is being updated. Please contact the AMS hotline 039.89.89.333 for detailed advice.</p>',1023,NULL,NULL,'uploads/images/ams/cta-bg.jpg',NULL,NULL,63,64,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,1,0,'page',0,0,0,0,1,'thuong-hieu',NULL,NULL,NULL,1),(524,'Theo phân loại','By category',NULL,NULL,'Theo phân loại','By category','<p>Theo phân loại của AMS đang được cập nhật. Vui lòng liên hệ hotline 039.89.89.333 để được tư vấn chi tiết.</p>','<p>The by-category section of AMS is being updated. Please contact the AMS hotline 039.89.89.333 for detailed advice.</p>',1024,NULL,NULL,NULL,NULL,NULL,65,66,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,1,0,'page',0,0,0,0,1,'',NULL,NULL,NULL,1),(525,'Theo chức năng','By function',NULL,NULL,'Theo chức năng','By function','<p>Theo chức năng của AMS đang được cập nhật. Vui lòng liên hệ hotline 039.89.89.333 để được tư vấn chi tiết.</p>','<p>The by-function section of AMS is being updated. Please contact the AMS hotline 039.89.89.333 for detailed advice.</p>',1025,NULL,NULL,NULL,NULL,NULL,67,68,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,1,0,'page',0,0,0,0,1,'',NULL,NULL,NULL,1),(526,'Thông tin pháp lý','Legal information',NULL,NULL,'Thông tin pháp lý','Legal information','<h2>Đơn vị chủ quản</h2><p>Công ty TNHH AMS Việt Nam<br>Trụ sở: Số 19A, ngách 57, ngõ 640, Nguyễn Văn Cừ, P. Bồ Đề, Hà Nội<br>Hotline: <a href=\"tel:0398989333\">039.89.89.333</a><br>Email: <a href=\"mailto:info@amsvn.net\">info@amsvn.net</a></p><h2>Lưu trữ website</h2><p>Website được lưu trữ và vận hành trên hạ tầng máy chủ tại Việt Nam.</p><h2>Thiết kế và phát triển</h2><p>Thiết kế và phát triển bởi <a href=\"https://webpx.com.vn\" target=\"_blank\" rel=\"noopener\">Webpx</a>.</p><h2>Liên hệ</h2><p>Mọi câu hỏi liên quan đến nội dung website, vui lòng gửi về <a href=\"lien-he\">trang Liên hệ</a> hoặc email <a href=\"mailto:info@amsvn.net\">info@amsvn.net</a>.</p><h2>Dữ liệu cá nhân</h2><p>AMS Việt Nam chỉ thu thập thông tin khách hàng tự nguyện cung cấp qua biểu mẫu liên hệ và yêu cầu báo giá (họ tên, công ty, số điện thoại, email, tỉnh/thành). Thông tin được dùng để phản hồi yêu cầu và không chia sẻ cho bên thứ ba.</p><h3>Thông tin được thu thập</h3><table><tr><th>Biểu mẫu</th><th>Thông tin</th><th>Mục đích</th></tr><tr><td>Yêu cầu báo giá</td><td>Họ tên, số điện thoại, email, sản phẩm quan tâm</td><td>Gửi báo giá, tư vấn sản phẩm</td></tr><tr><td>Liên hệ</td><td>Họ tên, công ty, số điện thoại, email, tỉnh/thành</td><td>Phản hồi yêu cầu, gửi tài liệu kỹ thuật</td></tr></table><h4>Quyền của khách hàng</h4><ol><li>Yêu cầu xem thông tin AMS đang lưu.</li><li>Yêu cầu chỉnh sửa thông tin chưa chính xác.</li><li>Yêu cầu xoá thông tin và ngừng nhận liên hệ.</li></ol><p>Khách hàng có thể gửi các yêu cầu trên bất kỳ lúc nào qua email <a href=\"mailto:info@amsvn.net\">info@amsvn.net</a>.</p><blockquote>AMS Việt Nam cam kết bảo mật thông tin khách hàng và chỉ dùng cho mục đích phục vụ yêu cầu báo giá, tư vấn kỹ thuật.</blockquote><h2>Nhãn hiệu</h2><p>Các tên thương hiệu và nhãn hiệu sản phẩm xuất hiện trên website (Shin-Etsu, Henkel, Dow, 3M, DuPont…) thuộc quyền sở hữu của các chủ sở hữu tương ứng.</p>','<p>Legal information of AMS is being updated. Please contact the AMS hotline 039.89.89.333 for detailed advice.</p>',1026,NULL,NULL,NULL,NULL,NULL,69,70,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,'page',0,0,0,0,1,'',NULL,NULL,NULL,1),(527,'Điều khoản & điều kiện','Terms & conditions',NULL,NULL,'Điều khoản & điều kiện','Terms & conditions','<p>Điều khoản & điều kiện của AMS đang được cập nhật. Vui lòng liên hệ hotline 039.89.89.333 để được tư vấn chi tiết.</p>','<p>The terms & conditions of AMS is being updated. Please contact the AMS hotline 039.89.89.333 for detailed advice.</p>',1027,NULL,NULL,NULL,NULL,NULL,71,72,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,'page',0,0,0,0,1,'',NULL,NULL,NULL,1),(528,'Điều khoản sử dụng','Terms of use',NULL,NULL,'Điều khoản sử dụng','Terms of use','<p>Điều khoản sử dụng của AMS đang được cập nhật. Vui lòng liên hệ hotline 039.89.89.333 để được tư vấn chi tiết.</p>','<p>The terms of use of AMS is being updated. Please conta