INSERT INTO `faqs` VALUES (6,'AMS cung cấp những sản phẩm và giải pháp nào?','What products and solutions does AMS provide?',NULL,NULL,'AMS cung cấp vật liệu và giải pháp kỹ thuật cho 8 nhóm ngành: xe hơi, loa & tai nghe, mô-đun máy ảnh, chất bán dẫn, điện tử, thiết bị y tế, pin & năng lượng và xây dựng.','AMS provides materials and technical solutions for 8 industries: automotive, speakers & headphones, camera modules, semiconductors, electronics, medical devices, batteries & energy, and construction.','<p>AMS cung cấp vật liệu và giải pháp kỹ thuật cho 8 nhóm ngành: xe hơi, loa & tai nghe, mô-đun máy ảnh, chất bán dẫn, điện tử, thiết bị y tế, pin & năng lượng và xây dựng.</p>','<p>AMS provides materials and technical solutions for 8 industries: automotive, speakers & headphones, camera modules, semiconductors, electronics, medical devices, batteries & energy, and construction.</p>',1,1,1792059897,1792059897,6),(7,'Tôi có thể nhận hàng mẫu trước khi đặt hàng không?','Can I get samples before placing an order?',NULL,NULL,'Có. AMS hỗ trợ gửi mẫu thử miễn phí cho hầu hết vật liệu để nhà máy kiểm tra trên dây chuyền trước khi ra quyết định đặt hàng.','Yes. AMS provides free samples for most materials so factories can test them on the production line before deciding to order.','<p>Có. AMS hỗ trợ gửi mẫu thử miễn phí cho hầu hết vật liệu để nhà máy kiểm tra trên dây chuyền trước khi ra quyết định đặt hàng.</p>','<p>Yes. AMS provides free samples for most materials so factories can test them on the production line before deciding to order.</p>',1,1,1792059897,1792059897,5),(8,'Buổi tư vấn 1-1 diễn ra như thế nào?','How does the 1-on-1 consultation work?',NULL,NULL,'Kỹ sư AMS khảo sát yêu cầu kỹ thuật, điều kiện vận hành và chi phí hiện tại, sau đó đề xuất phương án vật liệu kèm báo giá chi tiết.','AMS engineers review your technical requirements, operating conditions and current costs, then propose a material solution with a detailed quotation.','<p>Kỹ sư AMS khảo sát yêu cầu kỹ thuật, điều kiện vận hành và chi phí hiện tại, sau đó đề xuất phương án vật liệu kèm báo giá chi tiết.</p>','<p>AMS engineers review your technical requirements, operating conditions and current costs, then propose a material solution with a detailed quotation.</p>',1,1,1792059897,1792059897,4),(9,'AMS tối ưu chi phí cho khách hàng bằng cách nào?','How does AMS help customers reduce costs?',NULL,NULL,'AMS đề xuất vật liệu thay thế tương đương, tối ưu quy cách cắt và kế hoạch giao hàng để giảm hao hụt và tồn kho cho nhà máy.','AMS proposes equivalent alternative materials and optimizes cutting specifications and delivery schedules to reduce waste and inventory for factories.','<p>AMS đề xuất vật liệu thay thế tương đương, tối ưu quy cách cắt và kế hoạch giao hàng để giảm hao hụt và tồn kho cho nhà máy.</p>','<p>AMS proposes equivalent alternative materials and optimizes cutting specifications and delivery schedules to reduce waste and inventory for factories.</p>',1,1,1792059897,1792059897,3),(10,'Thời gian giao hàng thông thường là bao lâu?','What is the usual delivery time?',NULL,NULL,'Hàng có sẵn giao trong 1–3 ngày làm việc tại khu vực phía Bắc; hàng đặt theo quy cách riêng từ 7–14 ngày tùy số lượng.','In-stock items are delivered within 1–3 working days in the northern region; custom-specification orders take 7–14 days depending on quantity.','<p>Hàng có sẵn giao trong 1–3 ngày làm việc tại khu vực phía Bắc; hàng đặt theo quy cách riêng từ 7–14 ngày tùy số lượng.</p>','<p>In-stock items are delivered within 1–3 working days in the northern region; custom-specification orders take 7–14 days depending on quantity.</p>',1,1,1792059897,1792059897,2),(11,'AMS có hỗ trợ kỹ thuật sau bán hàng không?','Does AMS provide after-sales technical support?',NULL,NULL,'Có. Đội ngũ kỹ thuật AMS đồng hành trong quá trình đưa vật liệu vào sản xuất và hỗ trợ xử lý sự cố ngay tại nhà máy khi cần.','Yes. The AMS technical team supports you while bringing materials into production and helps resolve issues on site at your factory when needed.','<p>Có. Đội ngũ kỹ thuật AMS đồng hành trong quá trình đưa vật liệu vào sản xuất và hỗ trợ xử lý sự cố ngay tại nhà máy khi cần.</p>','<p>Yes. The AMS technical team supports you while bringing materials into production and helps resolve issues on site at your factory when needed.</p>',1,1,1792059897,1792059897,1);
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

