,1),(345,'general_text_68','','',NULL,NULL,NULL,1),(346,'general_text_69','','',NULL,NULL,NULL,1),(347,'general_text_70','« Phát triển AMS cho một kỷ nguyên mới »','« Growing AMS for a new era »',NULL,NULL,NULL,1),(348,'general_text_71','« Ngành công nghiệp điện tử đang thay đổi với tốc độ chóng mặt. Giữa sự đổi mới không ngừng, cạnh tranh đã mở rộng ra toàn cầu, vượt qua mọi ranh giới ngành nghề. AMS đã phát triển năng lực cung cấp giải pháp trọn gói, bổ sung cho chức năng thương mại cơ bản bằng năng lực tại chỗ được vun đắp qua nhiều năm đáp ứng nhu cầu đa dạng của khách hàng. »','« The electronics industry is changing at a dizzying pace. Amid constant innovation, competition has gone global and crossed every industry boundary. AMS has built the capability to deliver turnkey solutions, complementing its core trading function with on-site capabilities developed over many years of meeting diverse customer needs. »',NULL,NULL,NULL,1),(349,'general_text_72','Ban lãnh đạo AMS','AMS Leadership',NULL,NULL,NULL,1),(350,'general_text_73','Thông điệp từ lãnh đạo','Message from the leadership',NULL,NULL,NULL,1),(351,'general_text_74','« Chúng tôi quyết định mình là ai »','« We decide who we are »',NULL,NULL,NULL,1),(352,'general_text_75','« Bằng việc không ngừng tích hợp nhiều chức năng dịch vụ – hoạch định & phát triển, đại lý thu mua, dịch vụ sản xuất, quản lý chất lượng & môi trường, mạng lưới logistics quốc tế – AMS sẽ phát triển thành một “công ty dịch vụ tích hợp”, đáp ứng nhu cầu ngày càng đa dạng của khách hàng. »','« By continually integrating service functions – planning & development, purchasing agency, manufacturing services, quality & environmental management and an international logistics network – AMS will grow into an “integrated service company” meeting increasingly diverse customer needs. »',NULL,NULL,NULL,1),(353,'general_text_76','AMS Việt Nam','AMS Vietnam',NULL,NULL,NULL,1),(354,'general_text_77','Advanced Materials Solution','Advanced Materials Solution',NULL,NULL,NULL,1),(355,'general_text_78','Giá trị cốt lõi của AMS','AMS core values',NULL,NULL,NULL,1),(356,'general_text_79','« Lãnh đạo bằng hành động – Đạo đức kinh doanh – Trao quyền – Chuyên nghiệp – Sẵn sàng thay đổi. Năm giá trị này là kim chỉ nam cho mọi hành động của đội ngũ AMS, để phục vụ tốt nhất lợi ích của khách hàng và xã hội. »','« Leading by action – Business ethics – Empowerment – Professionalism – Readiness to change. These five values guide every action of the AMS team in serving the best interests of customers and society. »',NULL,NULL,NULL,1),(357,'general_text_80','Đội ngũ AMS','The AMS team',NULL,NULL,NULL,1),(358,'general_text_81','Hà Nội – Hải Phòng – TP. Hồ Chí Minh','Hanoi – Hai Phong – Ho Chi Minh City',NULL,NULL,NULL,1),(359,'general_text_82','','',NULL,NULL,NULL,1),(360,'general_text_83','','',NULL,NULL,NULL,1),(361,'general_text_84','','',NULL,NULL,NULL,1),(362,'general_text_85','','',NULL,NULL,NULL,1),(363,'general_text_86','','',NULL,NULL,NULL,1),(364,'general_text_87','','',NULL,NULL,NULL,1),(365,'general_text_88','','',NULL,NULL,NULL,1),(366,'general_text_89','','',NULL,NULL,NULL,1),(367,'general_text_90','','',NULL,NULL,NULL,1),(368,'general_text_91','','',NULL,NULL,NULL,1),(369,'general_text_92','','',NULL,NULL,NULL,1),(370,'general_text_93','','',NULL,NULL,NULL,1),(371,'general_text_94','','',NULL,NULL,NULL,1),(372,'general_text_95','','',NULL,NULL,NULL,1),(373,'general_text_96','','',NULL,NULL,NULL,1),(374,'general_text_97','','',NULL,NULL,NULL,1),(375,'general_text_98','','',NULL,NULL,NULL,1),(376,'general_text_99','app/webroot/uploads/files/404.png','app/webroot/uploads/files/404.png',NULL,NULL,NULL,1),(377,'general_text_100','','',NULL,NULL,NULL,1),(378,'contact_thanks','','',NULL,NULL,NULL,1),(379,'search','','',NULL,NULL,NULL,1),(380,'search_key','Từ khóa tìm kiếm','Search keywords',NULL,NULL,NULL,1),(381,'general_text_101','','',NULL,NULL,NULL,1),(382,'general_text_102','','',NULL,NULL,NULL,1),(383,'general_text_103',