  `seo_keyword` varchar(255) DEFAULT NULL,
  `seo_keyword_en` varchar(255) DEFAULT NULL,
  `price` int(11) DEFAULT 0,
  `price_vip` int(11) NOT NULL DEFAULT 0,
  `price_gold` int(11) NOT NULL DEFAULT 0,
  `price_member` int(11) NOT NULL DEFAULT 0,
