INSERT INTO `products` VALUES (501,NULL,1030,'uploads/images/ams/cat-1.jpg',NULL,'uploads/images/ams/cat-1.jpg','<p><strong>3M Băng keo hai mặt acrylic VHB</strong> l&agrave; d&ograve;ng băng keo kết cấu l&otilde;i bọt acrylic đặc, được thiết kế để thay thế li&ecirc;n kết cơ kh&iacute; như v&iacute;t, đinh t&aacute;n hay mối h&agrave;n điểm. Lớp keo acrylic li&ecirc;n kết ngang cho lực b&aacute;m tăng dần theo thời gian, đạt khoảng 90% cường độ sau 24 giờ v&agrave; tối đa sau 72 giờ ở nhiệt độ ph&ograve;ng, gi&uacute;p mối gh&eacute;p bền vững cả trong m&ocirc;i trường ngo&agrave;i trời.</p>\r\n<h3>Ứng dụng ti&ecirc;u biểu</h3>\r\n<ul>\r\n<li>D&aacute;n thanh gia cường, khung xương cho cửa tủ điện, vỏ m&aacute;y, thang m&aacute;y</li>\r\n<li>Lắp k&iacute;nh mặt dựng, biển quảng c&aacute;o, bảng hiệu alu ngo&agrave;i trời</li>\r\n<li>Cố định m&agrave;n h&igrave;nh cảm ứng, ống k&iacute;nh, khung viền trong thiết bị điện tử</li>\r\n<li>Gắn ray, nẹp trang tr&iacute;, logo tr&ecirc;n &ocirc; t&ocirc; v&agrave; xe chuy&ecirc;n dụng</li>\r\n<li>Li&ecirc;n kết tấm nhựa kỹ thuật PC, PMMA, ABS với kim loại sơn tĩnh điện</li>\r\n</ul>\r\n<h3>Ưu điểm nổi bật</h3>\r\n<ol>\r\n<li>Ph&acirc;n bố ứng suất đều tr&ecirc;n to&agrave;n bề mặt, loại bỏ điểm tập trung lực quanh lỗ khoan</li>\r\n<li>Bề mặt ho&agrave;n thiện phẳng đẹp, kh&ocirc;ng lộ đầu v&iacute;t, kh&ocirc;ng cần m&agrave;i sau h&agrave;n</li>\r\n<li>L&agrave;m k&iacute;n nước, k&iacute;n bụi đồng thời với việc li&ecirc;n kết, giảm một c&ocirc;ng đoạn tr&aacute;m k&iacute;n</li>\r\n<li>L&otilde;i bọt đ&agrave;n hồi hấp thụ rung động v&agrave; b&ugrave; trừ gi&atilde;n nở nhiệt giữa kim loại v&agrave; k&iacute;nh</li>\r\n</ol>\r\n<h3>Th&ocirc;ng số ch&iacute;nh</h3>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<th>Chỉ ti&ecirc;u</th>\r\n<th>Gi&aacute; trị</th>\r\n</tr>\r\n<tr>\r\n<td>Độ d&agrave;y tổng</td>\r\n<td>1,1 mm</td>\r\n</tr>\r\n<tr>\r\n<td>B&oacute;c 90&deg; tr&ecirc;n th&eacute;p kh&ocirc;ng gỉ</td>\r\n<td>khoảng 60 N/25 mm</td>\r\n</tr>\r\n<tr>\r\n<td>Độ bền k&eacute;o vu&ocirc;ng g&oacute;c</td>\r\n<td>480 kPa</td>\r\n</tr>\r\n<tr>\r\n<td>Độ bền cắt động</td>\r\n<td>550 kPa</td>\r\n</tr>\r\n<tr>\r\n<td>Nhiệt độ l&agrave;m việc</td>\r\n<td>93 &deg;C d&agrave;i hạn, 150 &deg;C ngắn hạn</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<h4>Lưu &yacute; khi thi c&ocirc;ng</h4>\r\n<p>Bề mặt cần sạch, kh&ocirc;, kh&ocirc;ng dầu mỡ; lau bằng hỗn hợp cồn isopropyl v&agrave; nước tỉ lệ 1:1 trước khi d&aacute;n. Nhiệt độ thi c&ocirc;ng l&yacute; tưởng từ 21 đến 38 &deg;C, kh&ocirc;ng d&aacute;n dưới 10 &deg;C. Sau khi d&aacute;n phải miết đều với &aacute;p lực tối thiểu khoảng 100 kPa để keo tiếp x&uacute;c ho&agrave;n to&agrave;n với bề mặt. Với vật liệu năng lượng bề mặt thấp như PP, PE n&ecirc;n d&ugrave;ng th&ecirc;m lớp l&oacute;t tăng b&aacute;m (primer).</p>\r\n<blockquote>Lực b&aacute;m của VHB phụ thuộc v&agrave;o diện t&iacute;ch tiếp x&uacute;c thực tế, v&igrave; vậy c&ocirc;ng đoạn miết lăn quan trọng kh&ocirc;ng k&eacute;m việc chọn đ&uacute;ng độ d&agrave;y băng keo.</blockquote>\r\n<p>Li&ecirc;n hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn chọn độ d&agrave;y, m&agrave;u l&otilde;i v&agrave; nhận mẫu thử cho d&acirc;y chuyền lắp r&aacute;p của bạn.</p>','<p><strong>3M VHB Acrylic Double-Sided Tape</strong> is a structural tape with a solid acrylic foam core, designed to replace mechanical fasteners such as screws, rivets and spot welds. Its cross-linked acrylic adhesive builds strength over time, reaching about 90% of ultimate strength after 24 hours and full strength after 72 hours at room temperature, delivering durable bonds even in outdoor environments.</p>\r\n<h3>Typical Applications</h3>\r\n<ul>\r\n<li>Bonding stiffeners and frames for electrical cabinet doors, machine housings and elevators</li>\r\n<li>Mounting curtain wall glass, signage and outdoor aluminum composite signs</li>\r\n<li>Securing touchscreens, lenses and bezels in electronic devices</li>\r\n<li>Attaching rails, trim strips and emblems on cars and specialty vehicles</li>\r\n<li>Bonding engineering plastics such as PC, PMMA and ABS to powder-coated metal</li>\r\n</ul>\r\n<h3>Key Advantages</h3>\r\n<ol>\r\n<li>Distributes stress evenly across the entire bond area, eliminating stress concentrations around drilled holes</li>\r\n<li>Clean, flat finished surfaces with no visible screw heads and no post-weld grinding</li>\r\n<li>Seals against water and dust while bonding, eliminating a separate sealing step</li>\r\n<li>Viscoelastic foam core absorbs vibration and accommodates differential thermal expansion between metal and glass</li>\r\n</ol>\r\n<h3>Key Specifications</h3>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<th>Property</th>\r\n<th>Value</th>\r\n</tr>\r\n<tr>\r\n<td>Total thickness</td>\r\n<td>1.1 mm</td>\r\n</tr>\r\n<tr>\r\n<td>90&deg; peel on stainless steel</td>\r\n<td>approx. 60 N/25 mm</td>\r\n</tr>\r\n<tr>\r\n<td>Normal tensile strength</td>\r\n<td>480 kPa</td>\r\n</tr>\r\n<tr>\r\n<td>Dynamic shear strength</td>\r\n<td>550 kPa</td>\r\n</tr>\r\n<tr>\r\n<td>Service temperature</td>\r\n<td>93 &deg;C long-term, 150 &deg;C short-term</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<h4>Application Notes</h4>\r\n<p>Surfaces must be clean, dry and free of oil and grease; wipe with a 1:1 mixture of isopropyl alcohol and water before bonding. The ideal application temperature is 21 to 38 &deg;C; do not apply below 10 &deg;C. After application, press firmly and evenly with a pressure of at least about 100 kPa to ensure full adhesive contact with the surface. For low surface energy materials such as PP and PE, use an adhesion promoter (primer).</p>\r\n<blockquote>VHB bond strength depends on the actual contact area, so the roll-down step is just as important as choosing the right tape thickness.</blockquote>\r\n<p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on thickness and core color selection, and to request samples for your assembly line.</p>','<table>\r\n<tbody>\r\n<tr>\r\n<td>Loại sản phẩm</td>\r\n<td>Băng keo hai mặt kết cấu</td>\r\n</tr>\r\n<tr>\r\n<td>Thương hiệu</td>\r\n<td>3M</td>\r\n</tr>\r\n<tr>\r\n<td>Gốc h&oacute;a học</td>\r\n<td>L&otilde;i bọt acrylic đặc, keo acrylic li&ecirc;n kết ngang</td>\r\n</tr>\r\n<tr>\r\n<td>M&agrave;u sắc</td>\r\n<td>X&aacute;m (c&oacute; loại đen, trắng, trong suốt)</td>\r\n</tr>\r\n<tr>\r\n<td>Số th&agrave;nh phần</td>\r\n<td>1 (dạng cuộn c&oacute; lớp l&oacute;t t&aacute;ch)</td>\r\n</tr>\r\n<tr>\r\n<td>Độ d&agrave;y</td>\r\n<td>1,1 mm</td>\r\n</tr>\r\n<tr>\r\n<td>Tỷ trọng l&otilde;i bọt</td>\r\n<td>khoảng 720 kg/m&sup3;</td>\r\n</tr>\r\n<tr>\r\n<td>Độ b&aacute;m d&iacute;nh b&oacute;c 90&deg;</td>\r\n<td>khoảng 60 N/25 mm</td>\r\n</tr>\r\n<tr>\r\n<td>Độ bền k&eacute;o vu&ocirc;ng g&oacute;c</td>\r\n<td>480 kPa</td>\r\n</tr>\r\n<tr>\r\n<td>Độ bền cắt động</td>\r\n<td>550 kPa</td>\r\n</tr>\r\n<tr>\r\n<td>Nhiệt độ tối đa</td>\r\n<td>93 &deg;C d&agrave;i hạn / 150 &deg;C ngắn hạn</td>\r\n</tr>\r\n<tr>\r\n<td>Nhiệt độ thi c&ocirc;ng tối thiểu</td>\r\n<td>10 &deg;C</td>\r\n</tr>\r\n<tr>\r\n<td>Ti&ecirc;u chuẩn</td>\r\n<td>RoHS, REACH</td>\r\n</tr>\r\n</tbody>\r\n</table>','<table>\r\n<tbody>\r\n<tr>\r\n<td>Product type</td>\r\n<td>Structural double-sided tape</td>\r\n</tr>\r\n<tr>\r\n<td>Brand</td>\r\n<td>3M</td>\r\n</tr>\r\n<tr>\r\n<td>Chemistry</td>\r\n<td>Solid acrylic foam core, cross-linked acrylic adhesive</td>\r\n</tr>\r\n<tr>\r\n<td>Color</td>\r\n<td>Gray (also available in black, white and clear)</td>\r\n</tr>\r\n<tr>\r\n<td>Components</td>\r\n<td>1 (roll with release liner)</td>\r\n</tr>\r\n<tr>\r\n<td>Thickness</td>\r\n<td>1.1 mm</td>\r\n</tr>\r\n<tr>\r\n<td>Foam core density</td>\r\n<td>approx. 720 kg/m&sup3;</td>\r\n</tr>\r\n<tr>\r\n<td>90&deg; peel adhesion</td>\r\n<td>approx. 60 N/25 mm</td>\r\n</tr>\r\n<tr>\r\n<td>Normal tensile strength</td>\r\n<td>480 kPa</td>\r\n</tr>\r\n<tr>\r\n<td>Dynamic shear strength</td>\r\n<td>550 kPa</td>\r\n</tr>\r\n<tr>\r\n<td>Maximum temperature</td>\r\n<td>93 &deg;C long-term / 150 &deg;C short-term</td>\r\n</tr>\r\n<tr>\r\n<td>Minimum application temperature</td>\r\n<td>10 &deg;C</td>\r\n</tr>\r\n<tr>\r\n<td>Standards</td>\r\n<td>RoHS, REACH</td>\r\n</tr>\r\n</tbody>\r\n</table>','<h4>Ứng dụng</h4>\r\n<p>Thay v&iacute;t, đinh t&aacute;n v&agrave; h&agrave;n điểm khi lắp r&aacute;p kim loại, k&iacute;nh, nhựa kỹ thuật; d&aacute;n thanh gia cường tủ điện, biển hiệu v&agrave; k&iacute;nh mặt dựng</p>\r\n<h4>Đặc t&iacute;nh</h4>\r\n<p>D&agrave;y 1,1 mm / B&aacute;m d&iacute;nh b&oacute;c 90&deg; khoảng 60 N/25 mm / Bền k&eacute;o 480 kPa / L&agrave;m việc d&agrave;i hạn 93 &deg;C, ngắn hạn 150 &deg;C</p>\r\n<h4>Bảo quản</h4>\r\n<p>15&ndash;25 &deg;C, độ ẩm 40&ndash;60%, d&ugrave;ng trong 24 th&aacute;ng</p>','<h4>Applications</h4>\r\n<p>Replaces screws, rivets and spot welds when joining metal, glass and engineering plastics; bonds stiffeners, signage and curtain wall glazing</p>\r\n<h4>Properties</h4>\r\n<p>Thickness 1.1 mm / 90&deg; peel adhesion approx. 60 N/25 mm / Tensile 480 kPa / Service 93 &deg;C long term, 150 &deg;C short term</p>\r\n<h4>Storage</h4>\r\n<p>15&ndash;25 &deg;C, 40&ndash;60% RH, use within 24 months</p>',1,0,1,0,'','','','','','',0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,'','{\"text\":[\"Mùa đông\",\"Mùa xuân\",\"Mùa hạ\",\"Mùa thu\",\"Ban ngày\",\"Ban đêm\"],\"value\":[\"0\",\"0\",\"0\",\"0\",\"0\",\"0\"]}',NULL,NULL,23,NULL,NULL,NULL,NULL,'',NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(502,NULL,1031,'uploads/images/ams/cat-2.jpg',NULL,'uploads/images/ams/cat-2.jpg','<p><strong>3M Băng keo PET chịu nhiệt</strong> là băng keo che chắn một mặt với lớp đế polyester mỏng và keo silicone chịu nhiệt, chuyên dùng trong các công đoạn có gia nhiệt như sơn tĩnh điện, hàn sóng hay sấy khô lớp phủ. Đế PET có độ bền kéo cao, không co ngót và bóc sạch sau chu kỳ nhiệt, giúp đường che chắn sắc nét và giảm thời gian làm sạch sản phẩm.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Che lỗ ren, bề mặt lắp ghép khi sơn tĩnh điện và sấy ở 180–200 °C</li><li>Che chân cắm, tiếp điểm vàng trên PCB khi hàn sóng hoặc phủ conformal</li><li>Che chắn khi mạ điện, anod hóa và phun cát bề mặt kim loại</li><li>Cố định đầu dây, cuộn dây trong biến áp và động cơ</li><li>Dán nối màng, cuộn vật liệu trên dây chuyền cán và sấy</li></ul><h3>Lợi ích khi sử dụng</h3><ol><li>Keo silicone giữ lực bám ổn định ở nhiệt độ cao, không bong mép khi nung</li><li>Bóc sạch không để lại cặn keo, không phải lau dung môi sau khi gỡ</li><li>Đế PET mỏng cho đường che sắc nét, dễ bế thành hình tròn, hình chữ nhật</li><li>Kháng hóa chất mạ và dung môi sơn, phù hợp nhiều quy trình xử lý bề mặt</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ dày tổng</td><td>0,06 mm</td></tr><tr><td>Độ bám dính trên thép</td><td>7 N/25 mm</td></tr><tr><td>Độ bền kéo</td><td>100 N/25 mm</td></tr><tr><td>Độ giãn dài khi đứt</td><td>khoảng 100%</td></tr><tr><td>Chịu nhiệt</td><td>200 °C trong 30 phút</td></tr></table><h4>Lưu ý khi thi công</h4><p>Dán băng keo lên bề mặt sạch, khô, đã nguội; miết kỹ mép băng để tránh sơn hoặc dung dịch thấm vào. Nên gỡ băng khi chi tiết còn ấm, kéo ngược chiều dán với góc khoảng 135° để đường viền sơn không bị bong. Không để băng keo tiếp xúc trực tiếp ngọn lửa hoặc vượt quá thời gian nung khuyến nghị.</p><blockquote>Với chi tiết cần che nhiều điểm giống nhau, đặt hàng băng keo bế sẵn dạng tròn hoặc theo bản vẽ giúp tăng năng suất dán gấp ba đến bốn lần.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn khổ cuộn, gia công bế theo bản vẽ và báo giá theo số lượng.</p>','<p><strong>3M High-Temperature PET Tape</strong> is a single-sided masking tape with a thin polyester backing and a heat-resistant silicone adhesive, designed for heated processes such as powder coating, wave soldering and coating cure. The PET backing offers high tensile strength, does not shrink and removes cleanly after the thermal cycle, producing sharp masking lines and reducing part cleanup time.</p><h3>Typical Applications</h3><ul><li>Masking threaded holes and mating surfaces during powder coating and curing at 180–200 °C</li><li>Masking pins and gold contacts on PCBs during wave soldering or conformal coating</li><li>Masking during electroplating, anodizing and sandblasting of metal surfaces</li><li>Securing lead ends and windings in transformers and motors</li><li>Splicing films and material rolls on laminating and drying lines</li></ul><h3>Benefits</h3><ol><li>Silicone adhesive maintains stable adhesion at high temperatures with no edge lifting during baking</li><li>Removes cleanly with no adhesive residue and no solvent wipe-down after removal</li><li>Thin PET backing gives sharp masking lines and is easy to die-cut into circles and rectangles</li><li>Resists plating chemicals and paint solvents, suitable for a wide range of surface treatment processes</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Total thickness</td><td>0.06 mm</td></tr><tr><td>Adhesion to steel</td><td>7 N/25 mm</td></tr><tr><td>Tensile strength</td><td>100 N/25 mm</td></tr><tr><td>Elongation at break</td><td>approx. 100%</td></tr><tr><td>Heat resistance</td><td>200 °C for 30 minutes</td></tr></table><h4>Application Notes</h4><p>Apply the tape to a clean, dry, cooled surface; press the tape edges down firmly to prevent paint or solution from seeping underneath. Remove the tape while the part is still warm, pulling back at an angle of about 135° so the paint edge does not lift. Do not expose the tape to open flame or exceed the recommended bake time.</p><blockquote>For parts with many identical masking points, ordering pre-cut dots or custom die-cut shapes to your drawing can increase application throughput three to four times.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on roll widths, custom die-cutting to your drawings and volume pricing.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Băng keo che chắn chịu nhiệt một mặt</td></tr><tr><td>Thương hiệu</td><td>3M</td></tr><tr><td>Gốc hóa học</td><td>Đế polyester (PET), keo silicone</td></tr><tr><td>Màu sắc</td><td>Xanh lá trong</td></tr><tr><td>Số thành phần</td><td>1</td></tr><tr><td>Độ dày đế PET</td><td>0,025 mm</td></tr><tr><td>Độ dày tổng</td><td>0,06 mm</td></tr><tr><td>Độ bám dính trên thép</td><td>7 N/25 mm</td></tr><tr><td>Độ bền kéo</td><td>100 N/25 mm</td></tr><tr><td>Độ giãn dài khi đứt</td><td>khoảng 100%</td></tr><tr><td>Điện áp đánh thủng</td><td>5 kV</td></tr><tr><td>Nhiệt độ tối đa</td><td>200 °C (30 phút)</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-40 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Single-sided high-temperature masking tape</td></tr><tr><td>Brand</td><td>3M</td></tr><tr><td>Chemistry</td><td>Polyester (PET) backing, silicone adhesive</td></tr><tr><td>Color</td><td>Transparent green</td></tr><tr><td>Components</td><td>1</td></tr><tr><td>PET backing thickness</td><td>0.025 mm</td></tr><tr><td>Total thickness</td><td>0.06 mm</td></tr><tr><td>Adhesion to steel</td><td>7 N/25 mm</td></tr><tr><td>Tensile strength</td><td>100 N/25 mm</td></tr><tr><td>Elongation at break</td><td>approx. 100%</td></tr><tr><td>Breakdown voltage</td><td>5 kV</td></tr><tr><td>Maximum temperature</td><td>200 °C (30 minutes)</td></tr><tr><td>Minimum temperature</td><td>-40 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Che chắn chân linh kiện khi hàn sóng, hàn nhúng; che phủ bề mặt khi sơn tĩnh điện, mạ, phun cát; cố định cuộn dây khi gia nhiệt</p><h4>Đặc tính</h4><p>Dày 0,06 mm / Bám dính 7 N/25 mm / Chịu nhiệt 200 °C trong 30 phút / Bền kéo 100 N/25 mm / Bóc sạch không để lại keo</p><h4>Bảo quản</h4><p>Để trong thùng carton, nơi khô mát, tránh nắng trực tiếp</p>','<h4>Applications</h4><p>Masks leads in wave and dip soldering; protects surfaces during powder coating, plating and blasting</p><h4>Properties</h4><p>Thickness 0.06 mm / Adhesion 7 N/25 mm / Withstands 200 °C for 30 min / Tensile 100 N/25 mm / Removes cleanly, no residue</p><h4>Storage</h4><p>Keep in cartons in a cool, dry place away from sunlight</p>',1,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,23,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(503,NULL,1032,'uploads/images/ams/cat-2.jpg',NULL,'uploads/images/ams/cat-2.jpg','<p><strong>Bergquist Tấm tản nhiệt silicone</strong> là vật liệu giao diện nhiệt dạng tấm mềm, gồm nền silicone độn hạt gốm dẫn nhiệt, dùng để lấp đầy khe hở giữa linh kiện và bộ tản nhiệt. Nhờ độ mềm cao, tấm ôm sát các bề mặt có dung sai chiều cao khác nhau mà không tạo ứng suất lớn lên linh kiện, đồng thời đảm bảo cách điện giữa linh kiện và vỏ kim loại.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Truyền nhiệt từ MOSFET, IGBT, cuộn cảm xuống vỏ nhôm bộ nguồn và biến tần</li><li>Tản nhiệt cell pin và mạch BMS trong mô-đun pin xe điện, hệ lưu trữ năng lượng</li><li>Lấp khe giữa chip và khung tản trong thiết bị mạng, trạm viễn thông</li><li>Tản nhiệt bo mạch driver và chip LED công suất cao</li><li>Đệm truyền nhiệt cho ECU, camera và radar trên ô tô</li></ul><h3>Ưu điểm</h3><ol><li>Dải độ dẫn nhiệt rộng 1,5–6 W/m·K, dễ chọn đúng cấp theo công suất tỏa nhiệt</li><li>Độ mềm cao, nén được 20–40% chiều dày, bù dung sai lắp ráp tốt</li><li>Cách điện, chống cháy, thay thế cho miếng mica và mỡ tản nhiệt</li><li>Thi công sạch, có thể bế sẵn theo hình dạng, tháo lắp khi bảo trì</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ dẫn nhiệt</td><td>1,5–6 W/m·K</td></tr><tr><td>Độ dày tiêu chuẩn</td><td>0,5–5 mm</td></tr><tr><td>Độ cứng</td><td>30–60 Shore 00</td></tr><tr><td>Điện áp đánh thủng</td><td>trên 6 kV/mm</td></tr><tr><td>Nhiệt độ làm việc</td><td>-60 đến 200 °C</td></tr><tr><td>Cấp chống cháy</td><td>UL 94 V-0</td></tr></table><h4>Lưu ý khi thi công</h4><p>Chọn độ dày tấm lớn hơn khe hở thực tế khoảng 10–20% để đạt độ nén phù hợp. Gỡ màng bảo vệ một mặt, đặt tấm lên linh kiện, sau đó gỡ mặt còn lại rồi lắp tản nhiệt; tránh kéo giãn tấm hoặc để bụi bám lên bề mặt. Không nén quá 50% chiều dày để tránh tạo lực ép lớn lên mối hàn linh kiện.</p><blockquote>Độ dẫn nhiệt cao chưa chắc tốt nhất: với khe hở lớn, một tấm mềm hơn nhưng nén được nhiều thường cho trở nhiệt tổng thấp hơn.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn chọn cấp dẫn nhiệt, bế theo bản vẽ và nhận mẫu thử nghiệm nhiệt.</p>','<p><strong>Bergquist Silicone Thermal Pad</strong> is a soft sheet-form thermal interface material consisting of a silicone matrix filled with thermally conductive ceramic particles, used to fill the gap between components and heat sinks. Thanks to its high softness, the pad conforms closely to surfaces with varying height tolerances without placing significant stress on components, while providing electrical insulation between components and metal enclosures.</p><h3>Typical Applications</h3><ul><li>Transferring heat from MOSFETs, IGBTs and inductors to the aluminum housings of power supplies and inverters</li><li>Cooling battery cells and BMS circuits in EV battery modules and energy storage systems</li><li>Filling the gap between chips and heat spreaders in networking equipment and telecom base stations</li><li>Cooling driver boards and high-power LED chips</li><li>Thermal gap filling for ECUs, cameras and radar in automobiles</li></ul><h3>Advantages</h3><ol><li>Wide thermal conductivity range of 1.5–6 W/m·K, making it easy to match the grade to the heat load</li><li>High softness with 20–40% compressibility, providing excellent assembly tolerance compensation</li><li>Electrically insulating and flame retardant, replacing mica sheets and thermal grease</li><li>Clean application, available pre-cut to shape, and removable for maintenance</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Thermal conductivity</td><td>1.5–6 W/m·K</td></tr><tr><td>Standard thickness</td><td>0.5–5 mm</td></tr><tr><td>Hardness</td><td>30–60 Shore 00</td></tr><tr><td>Breakdown voltage</td><td>over 6 kV/mm</td></tr><tr><td>Service temperature</td><td>-60 to 200 °C</td></tr><tr><td>Flammability rating</td><td>UL 94 V-0</td></tr></table><h4>Application Notes</h4><p>Select a pad thickness about 10–20% greater than the actual gap to achieve proper compression. Remove the protective film from one side, place the pad on the component, then remove the other film and mount the heat sink; avoid stretching the pad or allowing dust onto its surface. Do not compress beyond 50% of the thickness to avoid excessive force on component solder joints.</p><blockquote>Higher thermal conductivity is not always better: for large gaps, a softer pad that compresses more often delivers lower overall thermal resistance.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on thermal conductivity grade selection, die-cutting to your drawings and samples for thermal testing.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Tấm đệm dẫn nhiệt (gap pad)</td></tr><tr><td>Thương hiệu</td><td>Bergquist</td></tr><tr><td>Gốc hóa học</td><td>Silicone độn gốm dẫn nhiệt</td></tr><tr><td>Màu sắc</td><td>Xám, hồng, xanh tùy cấp dẫn nhiệt</td></tr><tr><td>Số thành phần</td><td>1 (dạng tấm)</td></tr><tr><td>Độ dẫn nhiệt</td><td>1,5–6 W/m·K</td></tr><tr><td>Độ dày</td><td>0,5–5 mm</td></tr><tr><td>Độ cứng</td><td>30–60 Shore 00</td></tr><tr><td>Tỷ trọng</td><td>2,9–3,2 g/cm³</td></tr><tr><td>Điện áp đánh thủng</td><td>trên 6 kV/mm</td></tr><tr><td>Điện trở suất khối</td><td>1×10¹² Ω·m</td></tr><tr><td>Nhiệt độ tối đa</td><td>200 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-60 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH, UL 94 V-0</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Thermally conductive gap pad</td></tr><tr><td>Brand</td><td>Bergquist</td></tr><tr><td>Chemistry</td><td>Silicone filled with thermally conductive ceramic</td></tr><tr><td>Color</td><td>Gray, pink or blue depending on conductivity grade</td></tr><tr><td>Components</td><td>1 (sheet)</td></tr><tr><td>Thermal conductivity</td><td>1.5–6 W/m·K</td></tr><tr><td>Thickness</td><td>0.5–5 mm</td></tr><tr><td>Hardness</td><td>30–60 Shore 00</td></tr><tr><td>Density</td><td>2.9–3.2 g/cm³</td></tr><tr><td>Breakdown voltage</td><td>over 6 kV/mm</td></tr><tr><td>Volume resistivity</td><td>1×10¹² Ω·m</td></tr><tr><td>Maximum temperature</td><td>200 °C</td></tr><tr><td>Minimum temperature</td><td>-60 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH, UL 94 V-0</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Lấp khe hở giữa linh kiện phát nhiệt và tản nhiệt, vỏ máy trong bộ nguồn, biến tần, mô-đun pin, đèn LED và điện tử ô tô</p><h4>Đặc tính</h4><p>Dẫn nhiệt 1,5–6 W/m·K / Dày 0,5–5 mm / Độ cứng 30–60 Shore 00 / Đánh thủng trên 6 kV/mm / Chống cháy UL 94 V-0</p><h4>Bảo quản</h4><p>Nơi khô mát, giữ nguyên màng bảo vệ đến khi lắp</p>','<h4>Applications</h4><p>Fills the gap between heat-generating parts and heat sinks or housings in power supplies, inverters, battery modules, LED and automotive units</p><h4>Properties</h4><p>Conductivity 1.5–6 W/m·K / Thickness 0.5–5 mm / Hardness 30–60 Shore 00 / Breakdown over 6 kV/mm / Flame rated UL 94 V-0</p><h4>Storage</h4><p>Cool, dry place; keep the liners on until assembly</p>',1,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,26,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(504,NULL,1033,'uploads/images/ams/cat-4.jpg',NULL,'uploads/images/ams/cat-4.jpg','<p><strong>Henkel Keo tản nhiệt hai thành phần</strong> là keo kết cấu dẫn nhiệt gốc epoxy biến tính, vừa tạo liên kết cơ học bền chắc vừa dẫn nhiệt từ linh kiện ra bộ tản nhiệt. Sản phẩm phù hợp với các thiết kế cần loại bỏ kẹp, vít giữ linh kiện, giúp thu gọn kết cấu và tăng độ tin cậy dưới rung động trong thiết bị nguồn và pin.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Dán cell pin vào khay làm mát trong mô-đun pin xe điện, xe máy điện</li><li>Gắn transistor, diode công suất lên tản nhiệt nhôm không cần vít</li><li>Cố định cuộn cảm, biến áp nhỏ trong bộ sạc và nguồn xung</li><li>Dán cảm biến nhiệt độ lên thanh cái, cell pin</li><li>Kết dính đế LED với tản nhiệt trong đèn chiếu sáng công nghiệp</li></ul><h3>Ưu điểm</h3><ol><li>Vừa kết dính kết cấu vừa truyền nhiệt, giảm số chi tiết cơ khí</li><li>Tỷ lệ trộn 1:1 thuận tiện cho súng đôi và máy định lượng tự động</li><li>Đóng rắn ở nhiệt độ phòng, có thể gia nhiệt 80 °C để rút ngắn chu kỳ sản xuất</li><li>Cách điện, ít co ngót, chịu sốc nhiệt và rung động tốt</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ dẫn nhiệt</td><td>2,0 W/m·K</td></tr><tr><td>Độ nhớt sau trộn</td><td>khoảng 60.000 mPa·s</td></tr><tr><td>Thời gian thao tác</td><td>60 phút ở 25 °C</td></tr><tr><td>Đóng rắn</td><td>24 giờ ở 25 °C hoặc 1 giờ ở 80 °C</td></tr><tr><td>Độ bền cắt trên nhôm</td><td>8 MPa</td></tr><tr><td>Độ cứng sau đóng rắn</td><td>80 Shore D</td></tr></table><h4>Lưu ý khi thi công</h4><p>Khuấy đều riêng từng thành phần trước khi trộn vì chất độn gốm có thể lắng. Dùng vòi trộn tĩnh hoặc trộn tay đến khi màu đồng nhất, tránh cuốn bọt khí. Bề mặt nhôm nên được tẩy dầu và làm nhám nhẹ để tăng bám dính. Chiều dày lớp keo tối ưu từ 0,1 đến 0,3 mm; lớp quá dày sẽ làm tăng trở nhiệt.</p><blockquote>Khi dùng súng đôi, bóp bỏ một đoạn keo đầu vòi trộn khoảng 3–5 cm để đảm bảo tỷ lệ trộn chính xác trước khi bơm lên sản phẩm.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn quy cách đóng gói, thiết bị định lượng và thử nghiệm trên chi tiết thực tế.</p>','<p><strong>Henkel Two-Component Thermal Adhesive</strong> is a thermally conductive structural adhesive based on modified epoxy that both creates a strong mechanical bond and conducts heat from components to the heat sink. It is ideal for designs that eliminate clips and screws holding components, enabling more compact assemblies and greater reliability under vibration in power and battery equipment.</p><h3>Typical Applications</h3><ul><li>Bonding battery cells to cooling plates in EV and electric motorcycle battery modules</li><li>Mounting transistors and power diodes onto aluminum heat sinks without screws</li><li>Securing inductors and small transformers in chargers and switch-mode power supplies</li><li>Bonding temperature sensors to busbars and battery cells</li><li>Bonding LED bases to heat sinks in industrial lighting fixtures</li></ul><h3>Advantages</h3><ol><li>Provides both structural bonding and heat transfer, reducing the number of mechanical parts</li><li>1:1 mix ratio is convenient for dual cartridges and automatic meter-mix equipment</li><li>Cures at room temperature, or can be heated to 80 °C to shorten production cycle time</li><li>Electrically insulating, low shrinkage, with excellent thermal shock and vibration resistance</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Thermal conductivity</td><td>2.0 W/m·K</td></tr><tr><td>Mixed viscosity</td><td>approx. 60,000 mPa·s</td></tr><tr><td>Working time</td><td>60 minutes at 25 °C</td></tr><tr><td>Cure</td><td>24 hours at 25 °C or 1 hour at 80 °C</td></tr><tr><td>Shear strength on aluminum</td><td>8 MPa</td></tr><tr><td>Cured hardness</td><td>80 Shore D</td></tr></table><h4>Application Notes</h4><p>Stir each component separately before mixing, as the ceramic filler may settle. Use a static mixing nozzle or mix by hand until the color is uniform, avoiding air entrapment. Aluminum surfaces should be degreased and lightly abraded to improve adhesion. The optimal bond line thickness is 0.1 to 0.3 mm; an overly thick layer increases thermal resistance.</p><blockquote>When using dual cartridges, purge about 3–5 cm of adhesive from the mixing nozzle to ensure an accurate mix ratio before dispensing onto the part.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on packaging options, dispensing equipment and testing on your actual parts.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Keo kết cấu dẫn nhiệt</td></tr><tr><td>Thương hiệu</td><td>Henkel</td></tr><tr><td>Gốc hóa học</td><td>Epoxy biến tính độn gốm</td></tr><tr><td>Màu sắc</td><td>Phần A trắng, phần B xám; sau trộn xám nhạt</td></tr><tr><td>Số thành phần</td><td>2</td></tr><tr><td>Tỷ lệ trộn</td><td>1:1 theo thể tích</td></tr><tr><td>Độ dẫn nhiệt</td><td>2,0 W/m·K</td></tr><tr><td>Độ nhớt sau trộn</td><td>khoảng 60.000 mPa·s</td></tr><tr><td>Thời gian thao tác</td><td>60 phút ở 25 °C</td></tr><tr><td>Độ bền cắt trên nhôm</td><td>8 MPa</td></tr><tr><td>Độ cứng</td><td>80 Shore D</td></tr><tr><td>Nhiệt độ tối đa</td><td>150 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-40 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Thermally conductive structural adhesive</td></tr><tr><td>Brand</td><td>Henkel</td></tr><tr><td>Chemistry</td><td>Ceramic-filled modified epoxy</td></tr><tr><td>Color</td><td>Part A white, Part B gray; light gray when mixed</td></tr><tr><td>Components</td><td>2</td></tr><tr><td>Mix ratio</td><td>1:1 by volume</td></tr><tr><td>Thermal conductivity</td><td>2.0 W/m·K</td></tr><tr><td>Mixed viscosity</td><td>approx. 60,000 mPa·s</td></tr><tr><td>Working time</td><td>60 minutes at 25 °C</td></tr><tr><td>Shear strength on aluminum</td><td>8 MPa</td></tr><tr><td>Hardness</td><td>80 Shore D</td></tr><tr><td>Maximum temperature</td><td>150 °C</td></tr><tr><td>Minimum temperature</td><td>-40 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Kết dính và truyền nhiệt cho cell pin, mô-đun nguồn, cảm biến công suất, cuộn cảm và tản nhiệt nhôm trong bộ sạc, biến tần</p><h4>Đặc tính</h4><p>Dẫn nhiệt 2,0 W/m·K / Tỷ lệ trộn 1:1 / Thời gian thao tác 60 phút / Bền cắt 8 MPa / Làm việc -40 đến 150 °C</p><h4>Bảo quản</h4><p>5–25 °C, đậy kín, khuấy đều trước khi dùng</p>','<h4>Applications</h4><p>Bonds and conducts heat for battery cells, power modules, current sensors, inductors and aluminum heat sinks in chargers and inverters</p><h4>Properties</h4><p>Conductivity 2.0 W/m·K / Mix ratio 1:1 / Working time 60 min / Shear strength 8 MPa / Service range -40 to 150 °C</p><h4>Storage</h4><p>5–25 °C, keep sealed, stir before use</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,21,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(505,NULL,1034,'uploads/images/ams/cat-3.jpg',NULL,'uploads/images/ams/cat-3.jpg','<p><strong>DuPont Màng cách điện polyimide</strong> là màng polymer hiệu năng cao giữ được tính chất cơ, điện ổn định trong dải nhiệt độ cực rộng, từ môi trường đông lạnh sâu tới 400 °C. Với độ bền điện môi rất cao trên một độ dày mỏng, màng polyimide là lựa chọn tiêu chuẩn cho cách điện cuộn dây, mạch in mềm và các chi tiết cần cách điện trong không gian hẹp.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Cách điện rãnh, lớp giữa các cuộn dây trong động cơ và máy biến áp</li><li>Vật liệu nền cho bo mạch mềm FPC và cáp dẹt</li><li>Quấn cách điện cell pin, thanh cái và đầu cực trong pack pin</li><li>Băng cách điện cho cuộn dây từ, cảm biến và rơ le</li><li>Che chắn bo mạch trong công đoạn hàn reflow và hàn sóng</li></ul><h3>Ưu điểm</h3><ol><li>Độ bền điện môi cao, cho phép thu nhỏ kích thước cách điện</li><li>Không nóng chảy, ổn định kích thước khi chịu nhiệt liên tục</li><li>Cơ tính tốt, chống rách, chịu uốn gấp nhiều lần</li><li>Kháng dung môi, dầu biến áp và bức xạ, tuổi thọ dài</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ dày tiêu chuẩn</td><td>25 µm (có 12,5–125 µm)</td></tr><tr><td>Điện áp đánh thủng</td><td>7 kV ở 25 µm</td></tr><tr><td>Độ bền kéo</td><td>230 MPa</td></tr><tr><td>Độ giãn dài khi đứt</td><td>khoảng 70%</td></tr><tr><td>Hằng số điện môi (1 kHz)</td><td>3,4</td></tr></table><h4>Lưu ý khi thi công</h4><p>Màng polyimide có độ hút ẩm nhất định; với ứng dụng cán phủ hoặc ép nhiệt nên sấy màng ở 120–150 °C trước khi gia công để tránh phồng rộp. Khi bế, cắt nên dùng dao sắc để mép không bị nứt. Cần giữ bề mặt sạch khi dán keo hoặc phủ lớp kết dính để đảm bảo độ bám.</p><blockquote>Nếu cần băng keo thay vì màng trơn, chọn loại màng polyimide phủ keo silicone để giữ được khả năng chịu nhiệt của toàn bộ hệ.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn độ dày, khổ cuộn và gia công xẻ, bế theo yêu cầu.</p>','<p><strong>DuPont Polyimide Insulating Film</strong> is a high-performance polymer film that maintains stable mechanical and electrical properties over an extremely wide temperature range, from cryogenic conditions up to 400 °C. With very high dielectric strength at minimal thickness, polyimide film is the standard choice for coil insulation, flexible printed circuits and components requiring insulation in tight spaces.</p><h3>Typical Applications</h3><ul><li>Slot and interlayer insulation between windings in motors and transformers</li><li>Base material for flexible printed circuits (FPC) and flat cables</li><li>Insulating wrap for battery cells, busbars and terminals in battery packs</li><li>Insulating tape for magnet coils, sensors and relays</li><li>Masking circuit boards during reflow and wave soldering</li></ul><h3>Advantages</h3><ol><li>High dielectric strength, allowing reduced insulation dimensions</li><li>Does not melt and remains dimensionally stable under continuous heat</li><li>Good mechanical properties, tear resistant and withstands repeated flexing</li><li>Resistant to solvents, transformer oil and radiation, with a long service life</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Standard thickness</td><td>25 µm (12.5–125 µm available)</td></tr><tr><td>Breakdown voltage</td><td>7 kV at 25 µm</td></tr><tr><td>Tensile strength</td><td>230 MPa</td></tr><tr><td>Elongation at break</td><td>approx. 70%</td></tr><tr><td>Dielectric constant (1 kHz)</td><td>3.4</td></tr></table><h4>Application Notes</h4><p>Polyimide film absorbs some moisture; for laminating or heat-pressing applications, dry the film at 120–150 °C before processing to prevent blistering. Use sharp blades when die-cutting or slitting so the edges do not crack. Keep the surface clean when applying adhesive or bonding layers to ensure good adhesion.</p><blockquote>If you need a tape rather than plain film, choose a polyimide film with silicone adhesive to retain the heat resistance of the entire system.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on thickness, roll widths and custom slitting and die-cutting.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Màng cách điện</td></tr><tr><td>Thương hiệu</td><td>DuPont</td></tr><tr><td>Gốc hóa học</td><td>Polyimide</td></tr><tr><td>Màu sắc</td><td>Hổ phách</td></tr><tr><td>Số thành phần</td><td>1 (dạng màng cuộn)</td></tr><tr><td>Độ dày</td><td>12,5–125 µm</td></tr><tr><td>Điện áp đánh thủng</td><td>7 kV ở 25 µm</td></tr><tr><td>Hằng số điện môi</td><td>3,4 ở 1 kHz</td></tr><tr><td>Điện trở suất khối</td><td>1×10¹⁷ Ω·cm</td></tr><tr><td>Độ bền kéo</td><td>230 MPa</td></tr><tr><td>Độ giãn dài khi đứt</td><td>khoảng 70%</td></tr><tr><td>Nhiệt độ tối đa</td><td>400 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-269 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH, UL 94 V-0</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Insulating film</td></tr><tr><td>Brand</td><td>DuPont</td></tr><tr><td>Chemistry</td><td>Polyimide</td></tr><tr><td>Color</td><td>Amber</td></tr><tr><td>Components</td><td>1 (film roll)</td></tr><tr><td>Thickness</td><td>12.5–125 µm</td></tr><tr><td>Breakdown voltage</td><td>7 kV at 25 µm</td></tr><tr><td>Dielectric constant</td><td>3.4 at 1 kHz</td></tr><tr><td>Volume resistivity</td><td>1×10¹⁷ Ω·cm</td></tr><tr><td>Tensile strength</td><td>230 MPa</td></tr><tr><td>Elongation at break</td><td>approx. 70%</td></tr><tr><td>Maximum temperature</td><td>400 °C</td></tr><tr><td>Minimum temperature</td><td>-269 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH, UL 94 V-0</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Cách điện cuộn dây động cơ, biến áp; làm nền bo mạch mềm; quấn cách điện cell pin, thanh cái; che chắn khi hàn và gia nhiệt</p><h4>Đặc tính</h4><p>Dày 25 µm / Đánh thủng 7 kV / Bền kéo 230 MPa / Hằng số điện môi 3,4 / Làm việc -269 đến 400 °C, tự dập tắt lửa</p><h4>Bảo quản</h4><p>Bao bì kín, nơi khô ráo, tránh gấp nếp và trầy xước</p>','<h4>Applications</h4><p>Insulates motor and transformer windings; serves as flexible circuit base film; wraps battery cells and busbars; masks during soldering</p><h4>Properties</h4><p>Thickness 25 µm / Breakdown 7 kV / Tensile 230 MPa / Dielectric constant 3.4 / Service -269 to 400 °C, self-extinguishing</p><h4>Storage</h4><p>Sealed packaging, dry place, avoid creasing and scratches</p>',1,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,24,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(506,NULL,1035,'uploads/images/ams/cat-5.jpg',NULL,'uploads/images/ams/cat-5.jpg','<p><strong>DuPont Giấy cách điện Nomex</strong> là giấy aramid được ép cán ở nhiệt độ cao, kết hợp độ bền điện môi lớn với khả năng chịu nhiệt cấp H. Vật liệu giữ cơ tính và tính cách điện ổn định qua nhiều năm vận hành liên tục ở nhiệt độ cao, là tiêu chuẩn phổ biến trong chế tạo và quấn lại động cơ, máy biến áp khô.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Cách điện rãnh, nêm rãnh và cách điện pha trong động cơ điện</li><li>Cách điện lớp, đầu cuộn trong máy biến áp khô và biến áp đúc</li><li>Ống lót, vòng đệm cách điện trong máy phát và cuộn kháng</li><li>Lót cách điện cho pack pin, thanh cái và tủ điện</li><li>Cách điện cuộn dây động cơ kéo, máy nén và thiết bị gia dụng</li></ul><h3>Vì sao nên chọn</h3><ol><li>Chịu nhiệt cấp H, nâng cao tuổi thọ và công suất định mức của thiết bị</li><li>Mềm dẻo, dễ gấp, dập rãnh mà không nứt gãy</li><li>Tự dập tắt lửa, không nóng chảy, không nhỏ giọt khi cháy</li><li>Tương thích tốt với vecni tẩm, nhựa epoxy và dầu cách điện</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ dày</td><td>0,05–0,76 mm</td></tr><tr><td>Độ bền điện môi</td><td>20–30 kV/mm</td></tr><tr><td>Cấp chịu nhiệt</td><td>H (180 °C), làm việc tới 220 °C</td></tr><tr><td>Tỷ trọng</td><td>0,7–1,1 g/cm³</td></tr><tr><td>Độ bền kéo dọc</td><td>khoảng 100 N/cm ở 0,25 mm</td></tr></table><h4>Lưu ý khi thi công</h4><p>Giấy aramid hút ẩm từ không khí, độ ẩm có thể làm giảm độ bền điện môi; nên sấy ở 105–120 °C trước khi tẩm vecni đối với thiết bị điện áp cao. Khi gấp mép, dập rãnh nên dùng khuôn có bán kính phù hợp với độ dày giấy. Bảo quản cuộn hoặc tấm nằm phẳng, tránh đè nặng làm biến dạng.</p><blockquote>Với động cơ quấn lại, chọn giấy dày 0,18–0,25 mm cho rãnh stator cỡ vừa thường cho cân bằng tốt giữa độ bền điện và độ đầy rãnh.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn độ dày, xẻ cuộn theo khổ và báo giá cho xưởng quấn động cơ.</p>','<p><strong>DuPont Nomex Insulating Paper</strong> is an aramid paper calendered at high temperature, combining high dielectric strength with Class H thermal performance. The material retains its mechanical and electrical properties through years of continuous operation at elevated temperatures, making it a widely used standard in the manufacture and rewinding of motors and dry-type transformers.</p><h3>Typical Applications</h3><ul><li>Slot liners, slot wedges and phase insulation in electric motors</li><li>Layer and end-turn insulation in dry-type and cast resin transformers</li><li>Insulating sleeves and washers in generators and reactors</li><li>Insulating liners for battery packs, busbars and electrical panels</li><li>Winding insulation for traction motors, compressors and household appliances</li></ul><h3>Why Choose It</h3><ol><li>Class H thermal rating, extending equipment life and rated power</li><li>Flexible and easy to fold and slot-form without cracking</li><li>Self-extinguishing, does not melt or drip when burning</li><li>Highly compatible with impregnating varnishes, epoxy resins and insulating oils</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Thickness</td><td>0.05–0.76 mm</td></tr><tr><td>Dielectric strength</td><td>20–30 kV/mm</td></tr><tr><td>Thermal class</td><td>H (180 °C), operating up to 220 °C</td></tr><tr><td>Density</td><td>0.7–1.1 g/cm³</td></tr><tr><td>Tensile strength (MD)</td><td>approx. 100 N/cm at 0.25 mm</td></tr></table><h4>Application Notes</h4><p>Aramid paper absorbs moisture from the air, which can reduce dielectric strength; for high-voltage equipment, dry at 105–120 °C before varnish impregnation. When folding edges or forming slots, use tooling with a bend radius suited to the paper thickness. Store rolls or sheets flat and avoid heavy loads that could cause deformation.</p><blockquote>For motor rewinding, 0.18–0.25 mm paper in medium-sized stator slots usually offers a good balance between dielectric strength and slot fill.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on thickness, slitting to width and pricing for motor rewinding shops.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Giấy cách điện</td></tr><tr><td>Thương hiệu</td><td>DuPont</td></tr><tr><td>Gốc hóa học</td><td>Aramid (meta-aramid) ép cán</td></tr><tr><td>Màu sắc</td><td>Trắng ngà</td></tr><tr><td>Số thành phần</td><td>1 (dạng cuộn, tấm)</td></tr><tr><td>Độ dày</td><td>0,05–0,76 mm</td></tr><tr><td>Tỷ trọng</td><td>0,7–1,1 g/cm³</td></tr><tr><td>Độ bền điện môi</td><td>20–30 kV/mm</td></tr><tr><td>Hằng số điện môi</td><td>khoảng 2,5 ở 60 Hz</td></tr><tr><td>Độ bền kéo dọc</td><td>khoảng 100 N/cm (0,25 mm)</td></tr><tr><td>Cấp chịu nhiệt</td><td>H</td></tr><tr><td>Nhiệt độ tối đa</td><td>220 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-40 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH, UL 94 V-0</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Insulating paper</td></tr><tr><td>Brand</td><td>DuPont</td></tr><tr><td>Chemistry</td><td>Calendered aramid (meta-aramid)</td></tr><tr><td>Color</td><td>Off-white</td></tr><tr><td>Components</td><td>1 (rolls, sheets)</td></tr><tr><td>Thickness</td><td>0.05–0.76 mm</td></tr><tr><td>Density</td><td>0.7–1.1 g/cm³</td></tr><tr><td>Dielectric strength</td><td>20–30 kV/mm</td></tr><tr><td>Dielectric constant</td><td>approx. 2.5 at 60 Hz</td></tr><tr><td>Tensile strength (MD)</td><td>approx. 100 N/cm (0.25 mm)</td></tr><tr><td>Thermal class</td><td>H</td></tr><tr><td>Maximum temperature</td><td>220 °C</td></tr><tr><td>Minimum temperature</td><td>-40 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH, UL 94 V-0</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Cách điện rãnh stator, nêm rãnh, cách điện pha trong động cơ; cách điện lớp và đầu cuộn trong biến áp khô, máy phát</p><h4>Đặc tính</h4><p>Dày 0,05–0,76 mm / Bền điện môi 20–30 kV/mm / Cấp chịu nhiệt H 180 °C, làm việc tới 220 °C / Tỷ trọng 0,7–1,1 g/cm³</p><h4>Bảo quản</h4><p>Bao bì kín, nơi khô ráo, tránh hút ẩm trước khi gia công</p>','<h4>Applications</h4><p>Slot liners, wedges and phase insulation in electric motors; layer and end-turn insulation in dry-type transformers and generators</p><h4>Properties</h4><p>Thickness 0.05–0.76 mm / Dielectric strength 20–30 kV/mm / Class H 180 °C, up to 220 °C / Density 0.7–1.1 g/cm³</p><h4>Storage</h4><p>Sealed packaging, dry place, keep from moisture before use</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,24,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(507,NULL,1036,'uploads/images/ams/cat-4.jpg',NULL,'uploads/images/ams/cat-4.jpg','<p><strong>Adtech Mút xốp PU chống rung</strong> là mút polyurethane ô kín vi mô mật độ cao, được thiết kế cho các vị trí đệm, làm kín và giảm chấn trong thiết bị điện tử. Khác với mút xốp thông thường, vật liệu giữ được chiều dày và lực đàn hồi sau thời gian dài bị nén, nhờ đó duy trì hiệu quả chống rung, chống bụi suốt vòng đời sản phẩm.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Đệm giữa màn hình LCD, kính cảm ứng và khung vỏ</li><li>Gioăng chống bụi, chống ẩm cho vỏ thiết bị cầm tay và đồng hồ đo</li><li>Đệm giảm chấn cho pack pin, ổ cứng, mô-đun camera</li><li>Lót chống rung cho quạt, loa và mô-tơ nhỏ</li><li>Đệm bù dung sai giữa bo mạch và vỏ máy</li></ul><h3>Ưu điểm</h3><ol><li>Biến dạng dư khi nén thấp, không xẹp theo thời gian</li><li>Lực nén ổn định trong dải nhiệt độ rộng, không cứng lại khi lạnh</li><li>Cấu trúc ô kín chống bụi, chống ẩm hiệu quả</li><li>Dễ cán keo hai mặt và bế chính xác theo bản vẽ</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Tỷ trọng</td><td>240–400 kg/m³</td></tr><tr><td>Độ dày</td><td>0,8–6 mm</td></tr><tr><td>Lực nén ở 25% biến dạng</td><td>35–140 kPa</td></tr><tr><td>Biến dạng dư khi nén</td><td>dưới 5%</td></tr><tr><td>Nhiệt độ làm việc</td><td>-40 đến 90 °C</td></tr></table><h4>Lưu ý khi thi công</h4><p>Thiết kế khe hở sao cho mút được nén 20–50% chiều dày để đạt hiệu quả làm kín và giảm chấn tốt nhất. Với gioăng dạng khung, nên chọn mút đã cán sẵn keo một mặt hoặc hai mặt để định vị nhanh. Bề mặt dán cần sạch, khô; tránh kéo căng mút khi dán vì sẽ làm thay đổi kích thước sau khi phục hồi.</p><blockquote>Chọn tỷ trọng thấp cho vị trí cần lực nén nhẹ quanh màn hình mỏng, tỷ trọng cao cho vị trí cần đỡ tải như pack pin.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn chọn tỷ trọng, cán keo và gia công bế theo bản vẽ.</p>','<p><strong>Adtech PU Anti-Vibration Foam</strong> is a high-density microcellular closed-cell polyurethane foam designed for cushioning, sealing and damping in electronic devices. Unlike conventional foams, it retains its thickness and resilience after prolonged compression, maintaining effective vibration and dust protection throughout the product\'s life.</p><h3>Typical Applications</h3><ul><li>Cushioning between LCD screens, touch glass and housings</li><li>Dust and moisture gaskets for handheld device housings and meters</li><li>Shock-absorbing pads for battery packs, hard drives and camera modules</li><li>Anti-vibration liners for fans, speakers and small motors</li><li>Tolerance-compensating pads between circuit boards and enclosures</li></ul><h3>Advantages</h3><ol><li>Low compression set, does not flatten over time</li><li>Consistent compression force over a wide temperature range, does not stiffen in the cold</li><li>Closed-cell structure provides effective dust and moisture sealing</li><li>Easy to laminate with double-sided adhesive and die-cut precisely to drawings</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Density</td><td>240–400 kg/m³</td></tr><tr><td>Thickness</td><td>0.8–6 mm</td></tr><tr><td>Compression force at 25% deflection</td><td>35–140 kPa</td></tr><tr><td>Compression set</td><td>below 5%</td></tr><tr><td>Service temperature</td><td>-40 to 90 °C</td></tr></table><h4>Application Notes</h4><p>Design the gap so the foam is compressed 20–50% of its thickness for optimal sealing and damping. For frame-style gaskets, choose foam pre-laminated with single- or double-sided adhesive for fast positioning. Bonding surfaces must be clean and dry; avoid stretching the foam during application, as this will change its dimensions after recovery.</p><blockquote>Choose a lower density where light compression force is needed around thin displays, and a higher density for load-bearing locations such as battery packs.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on density selection, adhesive lamination and die-cutting to your drawings.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Mút đệm chống rung, làm kín</td></tr><tr><td>Thương hiệu</td><td>Adtech</td></tr><tr><td>Gốc hóa học</td><td>Polyurethane ô kín vi mô</td></tr><tr><td>Màu sắc</td><td>Đen, xám</td></tr><tr><td>Số thành phần</td><td>1 (dạng tấm, cuộn)</td></tr><tr><td>Tỷ trọng</td><td>240–400 kg/m³</td></tr><tr><td>Độ dày</td><td>0,8–6 mm</td></tr><tr><td>Lực nén ở 25% biến dạng</td><td>35–140 kPa</td></tr><tr><td>Biến dạng dư khi nén</td><td>dưới 5%</td></tr><tr><td>Độ bền kéo</td><td>khoảng 0,8 MPa</td></tr><tr><td>Độ giãn dài khi đứt</td><td>khoảng 120%</td></tr><tr><td>Nhiệt độ tối đa</td><td>90 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-40 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH, UL 94 HF-1</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Anti-vibration and sealing foam</td></tr><tr><td>Brand</td><td>Adtech</td></tr><tr><td>Chemistry</td><td>Microcellular closed-cell polyurethane</td></tr><tr><td>Color</td><td>Black, gray</td></tr><tr><td>Components</td><td>1 (sheets, rolls)</td></tr><tr><td>Density</td><td>240–400 kg/m³</td></tr><tr><td>Thickness</td><td>0.8–6 mm</td></tr><tr><td>Compression force at 25% deflection</td><td>35–140 kPa</td></tr><tr><td>Compression set</td><td>below 5%</td></tr><tr><td>Tensile strength</td><td>approx. 0.8 MPa</td></tr><tr><td>Elongation at break</td><td>approx. 120%</td></tr><tr><td>Maximum temperature</td><td>90 °C</td></tr><tr><td>Minimum temperature</td><td>-40 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH, UL 94 HF-1</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Đệm chống rung, chống sốc cho màn hình, bo mạch, pin; gioăng chống bụi cho vỏ thiết bị điện tử, đồng hồ đo và thiết bị y tế</p><h4>Đặc tính</h4><p>Tỷ trọng 240–400 kg/m³ / Dày 0,8–6 mm / Biến dạng dư khi nén dưới 5% / Lực nén 25% 35–140 kPa / Làm việc -40 đến 90 °C</p><h4>Bảo quản</h4><p>Dạng tấm hoặc cuộn, nơi khô mát, không đè vật nặng</p>','<h4>Applications</h4><p>Cushions displays, boards and batteries against vibration and shock; dust gaskets for electronics housings and meters</p><h4>Properties</h4><p>Density 240–400 kg/m³ / Thickness 0.8–6 mm / Compression set under 5% / 25% CFD 35–140 kPa / Service range -40 to 90 °C</p><h4>Storage</h4><p>Sheets or rolls in a cool, dry place, no heavy loads on top</p>',1,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,31,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(508,NULL,1037,'uploads/images/ams/cat-1.jpg',NULL,'uploads/images/ams/cat-1.jpg','<p><strong>Dow Gioăng EPDM làm kín</strong> được chế tạo từ cao su ethylene propylene diene, loại elastomer có khả năng chịu thời tiết hàng đầu trong nhóm cao su thông dụng. Gioăng duy trì độ đàn hồi qua nhiều năm phơi nắng mưa, không nứt bề mặt do ozone, là lựa chọn tiêu chuẩn cho các vỏ thiết bị và tủ điện lắp đặt ngoài trời.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Gioăng cửa tủ điện, tủ điều khiển, hộp kỹ thuật ngoài trời</li><li>Làm kín vỏ đèn đường, đèn pha LED và hộp nguồn chống nước</li><li>Gioăng tủ viễn thông, trạm BTS và hộp phối quang</li><li>Đệm kín khung kính, cửa nhôm và vách ngăn</li><li>Gioăng ống gió, quạt và thiết bị điều hòa</li></ul><h3>Ưu điểm</h3><ol><li>Bền ozone, tia UV và thời tiết, tuổi thọ ngoài trời trên 10 năm</li><li>Đàn hồi tốt trong dải nhiệt rộng, không cứng giòn khi lạnh</li><li>Kháng nước, hơi nước và nhiều hóa chất gốc nước</li><li>Có dạng đặc, dạng xốp và dạng profile ép đùn theo yêu cầu</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ cứng</td><td>60–70 Shore A</td></tr><tr><td>Độ bền kéo</td><td>9 MPa</td></tr><tr><td>Độ giãn dài khi đứt</td><td>300%</td></tr><tr><td>Biến dạng dư khi nén (70 °C, 22 giờ)</td><td>25%</td></tr><tr><td>Nhiệt độ làm việc</td><td>-40 đến 120 °C</td></tr></table><h4>Lưu ý khi thi công</h4><p>EPDM không chịu dầu khoáng, xăng và dung môi hydrocarbon, vì vậy không dùng cho vị trí tiếp xúc trực tiếp dầu nhớt. Thiết kế rãnh lắp sao cho gioăng được nén 20–30% để đạt độ kín tối ưu. Tại vị trí nối đầu gioăng nên cắt vát và dán keo cyanoacrylate để tránh hở khe.</p><blockquote>Với cửa tủ đóng mở thường xuyên, gioăng EPDM xốp cho lực đóng nhẹ hơn mà vẫn kín nước, giúp bản lề và khóa bền hơn.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn chọn profile, độ cứng và gia công gioăng theo bản vẽ.</p>','<p><strong>Dow EPDM Sealing Gasket</strong> is made from ethylene propylene diene rubber, the elastomer with the best weather resistance among general-purpose rubbers. The gasket remains elastic through years of sun and rain exposure without ozone cracking, making it the standard choice for equipment enclosures and electrical cabinets installed outdoors.</p><h3>Typical Applications</h3><ul><li>Door gaskets for outdoor electrical cabinets, control panels and technical enclosures</li><li>Sealing street light housings, LED floodlights and waterproof power supply boxes</li><li>Gaskets for telecom cabinets, BTS stations and fiber distribution boxes</li><li>Seals for glazing frames, aluminum doors and partitions</li><li>Gaskets for air ducts, fans and HVAC equipment</li></ul><h3>Advantages</h3><ol><li>Resistant to ozone, UV and weathering, with an outdoor service life of over 10 years</li><li>Good elasticity over a wide temperature range, does not become hard or brittle in the cold</li><li>Resistant to water, steam and many water-based chemicals</li><li>Available in solid, sponge and custom extruded profile forms</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Hardness</td><td>60–70 Shore A</td></tr><tr><td>Tensile strength</td><td>9 MPa</td></tr><tr><td>Elongation at break</td><td>300%</td></tr><tr><td>Compression set (70 °C, 22 hours)</td><td>25%</td></tr><tr><td>Service temperature</td><td>-40 to 120 °C</td></tr></table><h4>Application Notes</h4><p>EPDM is not resistant to mineral oils, gasoline or hydrocarbon solvents, so do not use it where it will be in direct contact with oil or lubricants. Design the mounting groove so the gasket is compressed 20–30% for optimal sealing. At gasket joints, miter-cut the ends and bond them with cyanoacrylate adhesive to prevent gaps.</p><blockquote>For frequently opened cabinet doors, sponge EPDM gaskets provide a lighter closing force while remaining watertight, extending the life of hinges and locks.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on profile and hardness selection and custom gasket fabrication to your drawings.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Gioăng làm kín</td></tr><tr><td>Thương hiệu</td><td>Dow</td></tr><tr><td>Gốc hóa học</td><td>Cao su EPDM</td></tr><tr><td>Màu sắc</td><td>Đen</td></tr><tr><td>Số thành phần</td><td>1 (dạng profile, tấm, dải)</td></tr><tr><td>Độ cứng</td><td>60–70 Shore A</td></tr><tr><td>Tỷ trọng</td><td>1,20–1,30 g/cm³ (dạng đặc)</td></tr><tr><td>Độ bền kéo</td><td>9 MPa</td></tr><tr><td>Độ giãn dài khi đứt</td><td>300%</td></tr><tr><td>Biến dạng dư khi nén</td><td>25% (70 °C, 22 giờ)</td></tr><tr><td>Cấp bảo vệ khi lắp đúng</td><td>IP65–IP67</td></tr><tr><td>Nhiệt độ tối đa</td><td>120 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-40 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Sealing gasket</td></tr><tr><td>Brand</td><td>Dow</td></tr><tr><td>Chemistry</td><td>EPDM rubber</td></tr><tr><td>Color</td><td>Black</td></tr><tr><td>Components</td><td>1 (profiles, sheets, strips)</td></tr><tr><td>Hardness</td><td>60–70 Shore A</td></tr><tr><td>Density</td><td>1.20–1.30 g/cm³ (solid)</td></tr><tr><td>Tensile strength</td><td>9 MPa</td></tr><tr><td>Elongation at break</td><td>300%</td></tr><tr><td>Compression set</td><td>25% (70 °C, 22 hours)</td></tr><tr><td>Ingress protection when properly installed</td><td>IP65–IP67</td></tr><tr><td>Maximum temperature</td><td>120 °C</td></tr><tr><td>Minimum temperature</td><td>-40 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Làm kín cửa tủ điện, hộp đấu dây, thiết bị chiếu sáng và viễn thông ngoài trời; gioăng cửa máy, khung kính và hệ thống thông gió</p><h4>Đặc tính</h4><p>Độ cứng 60–70 Shore A / Bền kéo 9 MPa / Giãn dài 300% / Biến dạng dư khi nén 25% / Làm việc -40 đến 120 °C, đạt IP65–IP67</p><h4>Bảo quản</h4><p>Nơi khô mát, tránh ánh nắng và nguồn ozone</p>','<h4>Applications</h4><p>Seals electrical cabinet doors, junction boxes, outdoor lighting and telecom enclosures; gaskets for machine doors, glazing and ventilation</p><h4>Properties</h4><p>Hardness 60–70 Shore A / Tensile 9 MPa / Elongation 300% / Compression set 25% / Service -40 to 120 °C, rated IP65–IP67</p><h4>Storage</h4><p>Cool, dry place away from sunlight and ozone sources</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,22,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(509,NULL,1038,'uploads/images/ams/cat-5.jpg',NULL,'uploads/images/ams/cat-5.jpg','<p><strong>Dymax Lớp phủ bảo vệ bo mạch</strong> là vật liệu conformal coating gốc acrylate urethane, đóng rắn trong vài giây dưới đèn UV và không chứa dung môi. Cơ chế đóng rắn ẩm thứ cấp giúp phần keo nằm dưới linh kiện, nơi tia UV không chiếu tới, vẫn đóng rắn hoàn toàn. Giải pháp này rút ngắn chu kỳ sản xuất từ hàng giờ sấy xuống vài giây và loại bỏ phát thải dung môi.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Bo mạch ECU, cảm biến và mô-đun chiếu sáng trên ô tô</li><li>Bộ điều khiển PLC, biến tần và thiết bị đo lường công nghiệp</li><li>Driver LED và bộ nguồn lắp đặt ngoài trời</li><li>Bo mạch đồ gia dụng thông minh, máy giặt, điều hòa</li><li>Thiết bị viễn thông, đồng hồ đo điện nước</li></ul><h3>Ưu điểm</h3><ol><li>Đóng rắn trong 1–3 giây, có thể kiểm tra và đóng gói ngay sau khi phủ</li><li>Không dung môi, không VOC, không cần lò sấy dài và hệ thống hút khí</li><li>Phát huỳnh quang xanh dưới đèn UV, dễ kiểm tra độ phủ bằng camera AOI</li><li>Chống ẩm, sương muối và sốc nhiệt tốt, bám chắc trên mặt nạ hàn</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ nhớt</td><td>200–700 mPa·s</td></tr><tr><td>Thời gian đóng rắn UV</td><td>1–3 giây</td></tr><tr><td>Chiều dày lớp phủ khuyến nghị</td><td>25–200 µm</td></tr><tr><td>Độ bền điện môi</td><td>39 kV/mm</td></tr><tr><td>Độ cứng sau đóng rắn</td><td>khoảng 60 Shore D</td></tr></table><h4>Lưu ý khi thi công</h4><p>Bo mạch cần sạch cặn trợ hàn và khô hoàn toàn trước khi phủ. Có thể phủ bằng máy phun chọn lọc, quét hoặc nhúng; che các đầu nối, chân cắm cần tiếp xúc điện. Dùng đèn UV có bước sóng và cường độ phù hợp, đo liều chiếu định kỳ để đảm bảo bề mặt không còn dính. Vùng khuất sẽ đóng rắn bằng ẩm không khí trong 2–3 ngày.</p><blockquote>Đặt camera kiểm tra dưới đèn UV ngay sau trạm phủ giúp phát hiện điểm thiếu phủ trước khi bo mạch đi tiếp, tiết kiệm đáng kể chi phí sửa lỗi.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn vật liệu, thiết bị đèn UV và chạy thử trên bo mạch thực tế.</p>','<p><strong>Dymax PCB Conformal Coating</strong> is a solvent-free acrylated urethane conformal coating that cures in seconds under UV light. A secondary moisture-cure mechanism ensures that material in shadowed areas beneath components, where UV light cannot reach, still cures fully. This solution cuts production cycle time from hours of oven drying to just seconds and eliminates solvent emissions.</p><h3>Typical Applications</h3><ul><li>ECU, sensor and lighting module boards in automobiles</li><li>PLC controllers, inverters and industrial measuring instruments</li><li>LED drivers and power supplies installed outdoors</li><li>Circuit boards for smart home appliances, washing machines and air conditioners</li><li>Telecom equipment and electricity and water meters</li></ul><h3>Advantages</h3><ol><li>Cures in 1–3 seconds, allowing inspection and packaging immediately after coating</li><li>Solvent-free, zero VOC, with no need for long drying ovens or fume extraction systems</li><li>Fluoresces blue under UV light for easy coverage inspection with AOI cameras</li><li>Excellent resistance to moisture, salt spray and thermal shock, with strong adhesion to solder mask</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Viscosity</td><td>200–700 mPa·s</td></tr><tr><td>UV cure time</td><td>1–3 seconds</td></tr><tr><td>Recommended coating thickness</td><td>25–200 µm</td></tr><tr><td>Dielectric strength</td><td>39 kV/mm</td></tr><tr><td>Cured hardness</td><td>approx. 60 Shore D</td></tr></table><h4>Application Notes</h4><p>Boards must be free of flux residue and completely dry before coating. The coating can be applied by selective spraying, brushing or dipping; mask connectors and pins that require electrical contact. Use a UV lamp with the appropriate wavelength and intensity, and measure the UV dose periodically to ensure a tack-free surface. Shadowed areas will cure via atmospheric moisture within 2–3 days.</p><blockquote>Placing an inspection camera under UV light right after the coating station helps detect uncoated spots before boards move on, significantly reducing rework costs.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on materials and UV lamp equipment, and for trial runs on your actual boards.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Lớp phủ conformal coating</td></tr><tr><td>Thương hiệu</td><td>Dymax</td></tr><tr><td>Gốc hóa học</td><td>Acrylate urethane, đóng rắn UV và ẩm</td></tr><tr><td>Màu sắc</td><td>Trong suốt, phát huỳnh quang xanh</td></tr><tr><td>Số thành phần</td><td>1</td></tr><tr><td>Độ nhớt</td><td>200–700 mPa·s</td></tr><tr><td>Thời gian đóng rắn UV</td><td>1–3 giây</td></tr><tr><td>Chiều dày lớp phủ</td><td>25–200 µm</td></tr><tr><td>Độ cứng</td><td>khoảng 60 Shore D</td></tr><tr><td>Độ bền điện môi</td><td>39 kV/mm</td></tr><tr><td>Hằng số điện môi</td><td>khoảng 3,0 ở 1 MHz</td></tr><tr><td>Nhiệt độ tối đa</td><td>135 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-55 °C</td></tr><tr><td>Tiêu chuẩn</td><td>IPC-CC-830, UL 746E, RoHS, REACH</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Conformal coating</td></tr><tr><td>Brand</td><td>Dymax</td></tr><tr><td>Chemistry</td><td>Acrylated urethane, UV and moisture cure</td></tr><tr><td>Color</td><td>Clear, blue fluorescing</td></tr><tr><td>Components</td><td>1</td></tr><tr><td>Viscosity</td><td>200–700 mPa·s</td></tr><tr><td>UV cure time</td><td>1–3 seconds</td></tr><tr><td>Coating thickness</td><td>25–200 µm</td></tr><tr><td>Hardness</td><td>approx. 60 Shore D</td></tr><tr><td>Dielectric strength</td><td>39 kV/mm</td></tr><tr><td>Dielectric constant</td><td>approx. 3.0 at 1 MHz</td></tr><tr><td>Maximum temperature</td><td>135 °C</td></tr><tr><td>Minimum temperature</td><td>-55 °C</td></tr><tr><td>Standards</td><td>IPC-CC-830, UL 746E, RoHS, REACH</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Phủ bảo vệ bo mạch điện tử ô tô, bộ điều khiển công nghiệp, đèn LED và nguồn xung khỏi ẩm, bụi, hơi muối và ăn mòn</p><h4>Đặc tính</h4><p>Độ nhớt 200–700 mPa·s / Đóng rắn UV 1–3 giây / Lớp phủ 25–200 µm / Bền điện môi 39 kV/mm / Làm việc -55 đến 135 °C</p><h4>Bảo quản</h4><p>10–32 °C trong bình chắn sáng, tránh tia UV</p>','<h4>Applications</h4><p>Protects automotive electronics, industrial controllers, LED drivers and switching power supplies from moisture, dust, salt mist and corrosion</p><h4>Properties</h4><p>Viscosity 200–700 mPa·s / UV cure 1–3 s / Coating 25–200 µm / Dielectric strength 39 kV/mm / Service range -55 to 135 °C</p><h4>Storage</h4><p>10–32 °C in opaque containers, away from UV light</p>',1,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,25,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(510,NULL,1039,'uploads/images/ams/cat-3.jpg',NULL,'uploads/images/ams/cat-3.jpg','<p><strong>3M Màng bảo vệ bề mặt PE</strong> là màng polyethylene phủ keo có độ bám được kiểm soát, dùng để bảo vệ bề mặt hoàn thiện trong suốt chuỗi gia công, vận chuyển và lắp đặt. Màng giữ chắc trong các công đoạn cắt, chấn, đột dập nhưng vẫn bóc sạch dễ dàng khi bàn giao, giúp giảm tỷ lệ hàng lỗi do trầy xước.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Bảo vệ tấm inox, nhôm xước hairline khi cắt laser và chấn gấp</li><li>Phủ tôn mạ màu, tấm alu ốp mặt dựng trong vận chuyển</li><li>Bảo vệ tấm acrylic, polycarbonate khi cắt CNC và uốn nhiệt</li><li>Che bảo vệ kính, cửa nhôm kính tại công trình</li><li>Bảo vệ màn hình, vỏ thiết bị điện tử trên dây chuyền lắp ráp</li></ul><h3>Ưu điểm</h3><ol><li>Nhiều cấp độ bám phù hợp từ bề mặt bóng gương đến bề mặt nhám</li><li>Bóc sạch, không để lại vết keo, không làm đổi màu bề mặt</li><li>Ổn định UV, có thể để ngoài trời đến 6 tháng tại công trình</li><li>Độ giãn dài cao, không rách khi chấn gấp và dập sâu</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ dày</td><td>50–80 µm</td></tr><tr><td>Độ bám dính trên thép</td><td>0,5–3 N/25 mm</td></tr><tr><td>Độ bền kéo</td><td>25 MPa</td></tr><tr><td>Độ giãn dài khi đứt</td><td>400%</td></tr><tr><td>Thời gian chịu UV</td><td>6 tháng ngoài trời</td></tr></table><h4>Lưu ý khi thi công</h4><p>Dán màng lên bề mặt sạch, khô, nhiệt độ từ 15 đến 35 °C, dùng con lăn để không có bọt khí. Với tôn mạ màu và bề mặt sơn, chỉ dán màng sau khi lớp sơn đã khô hoàn toàn. Khi cắt laser, chọn loại màng chuyên dụng để tránh keo chảy vào mép cắt. Nên bóc màng trong thời hạn khuyến nghị để keo không bám chặt dần.</p><blockquote>Thử dán một mẫu nhỏ và để qua 7 ngày ở điều kiện thực tế trước khi chọn cấp độ bám cho đơn hàng lớn.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn cấp độ bám, khổ cuộn và in logo theo yêu cầu.</p>','<p><strong>3M PE Surface Protection Film</strong> is a polyethylene film coated with a controlled-tack adhesive, used to protect finished surfaces throughout fabrication, shipping and installation. The film holds firmly during cutting, bending and punching yet peels off cleanly at handover, reducing rejects caused by scratches.</p><h3>Typical Applications</h3><ul><li>Protecting hairline-finish stainless steel and aluminum sheets during laser cutting and press brake bending</li><li>Covering pre-painted steel sheets and aluminum composite facade panels during shipping</li><li>Protecting acrylic and polycarbonate sheets during CNC cutting and thermoforming</li><li>Protecting glass and aluminum-glass doors on construction sites</li><li>Protecting screens and electronic device housings on assembly lines</li></ul><h3>Advantages</h3><ol><li>Multiple tack levels to suit surfaces from mirror-polished to textured</li><li>Peels cleanly with no adhesive residue and no surface discoloration</li><li>UV stabilized, can remain outdoors on site for up to 6 months</li><li>High elongation, does not tear during bending and deep drawing</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Thickness</td><td>50–80 µm</td></tr><tr><td>Adhesion to steel</td><td>0.5–3 N/25 mm</td></tr><tr><td>Tensile strength</td><td>25 MPa</td></tr><tr><td>Elongation at break</td><td>400%</td></tr><tr><td>UV exposure resistance</td><td>6 months outdoors</td></tr></table><h4>Application Notes</h4><p>Apply the film to a clean, dry surface at 15 to 35 °C, using a roller to avoid air bubbles. For pre-painted steel and painted surfaces, apply the film only after the paint has fully dried. For laser cutting, choose a dedicated laser film to prevent adhesive from flowing into the cut edge. Remove the film within the recommended period so the adhesive does not gradually build up adhesion.</p><blockquote>Test a small sample and leave it for 7 days under real conditions before selecting the tack level for a large order.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on tack levels, roll widths and custom logo printing.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Màng bảo vệ bề mặt</td></tr><tr><td>Thương hiệu</td><td>3M</td></tr><tr><td>Gốc hóa học</td><td>Màng polyethylene, keo acrylic gốc nước</td></tr><tr><td>Màu sắc</td><td>Trong, xanh nhạt, đen trắng</td></tr><tr><td>Số thành phần</td><td>1 (dạng cuộn)</td></tr><tr><td>Độ dày</td><td>50–80 µm</td></tr><tr><td>Độ bám dính trên thép</td><td>0,5–3 N/25 mm</td></tr><tr><td>Độ bền kéo</td><td>25 MPa</td></tr><tr><td>Độ giãn dài khi đứt</td><td>400%</td></tr><tr><td>Khổ cuộn tối đa</td><td>1.250 mm</td></tr><tr><td>Thời gian chịu UV</td><td>6 tháng</td></tr><tr><td>Nhiệt độ tối đa</td><td>70 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-20 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Surface protection film</td></tr><tr><td>Brand</td><td>3M</td></tr><tr><td>Chemistry</td><td>Polyethylene film, water-based acrylic adhesive</td></tr><tr><td>Color</td><td>Clear, light blue, black and white</td></tr><tr><td>Components</td><td>1 (roll)</td></tr><tr><td>Thickness</td><td>50–80 µm</td></tr><tr><td>Adhesion to steel</td><td>0.5–3 N/25 mm</td></tr><tr><td>Tensile strength</td><td>25 MPa</td></tr><tr><td>Elongation at break</td><td>400%</td></tr><tr><td>Maximum roll width</td><td>1,250 mm</td></tr><tr><td>UV exposure resistance</td><td>6 months</td></tr><tr><td>Maximum temperature</td><td>70 °C</td></tr><tr><td>Minimum temperature</td><td>-20 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Bảo vệ bề mặt inox, nhôm, tôn mạ màu, kính, tấm acrylic và polycarbonate khỏi trầy xước trong gia công, vận chuyển và lắp đặt</p><h4>Đặc tính</h4><p>Dày 50–80 µm / Bám dính 0,5–3 N/25 mm / Bền kéo 25 MPa / Giãn dài 400% / Chịu UV ngoài trời 6 tháng, bóc sạch không để lại keo</p><h4>Bảo quản</h4><p>Cuộn đứng trong thùng, nơi khô mát, dùng trong 6 tháng</p>','<h4>Applications</h4><p>Protects stainless steel, aluminum, prepainted steel, glass, acrylic and polycarbonate sheet from scratches during fabrication and installation</p><h4>Properties</h4><p>Thickness 50–80 µm / Adhesion 0.5–3 N/25 mm / Tensile 25 MPa / Elongation 400% / 6 months outdoor UV, removes cleanly</p><h4>Storage</h4><p>Store rolls upright in cartons, cool and dry, use within 6 months</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,23,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(511,NULL,1056,'uploads/images/ams/sp-g747.jpg',NULL,'uploads/images/ams/loai-greases-and-oil-compounds.jpg,uploads/images/ams/cat-2.jpg,uploads/images/ams/loai-silicone-fluids.jpg,uploads/images/ams/sp-g40m.jpg','<p><strong>Shin-Etsu Mỡ tản nhiệt G-747</strong> là mỡ silicone dẫn nhiệt một thành phần, không đóng rắn, dùng để lấp đầy các khe hở vi mô giữa đế linh kiện công suất và bộ tản nhiệt. Nhờ dầu nền silicone ổn định và chất độn oxit kim loại phân bố đều, G-747 cho lớp tiếp xúc mỏng, trở nhiệt thấp và giữ tính chất ổn định trong thời gian dài, ít tách dầu và khô cứng.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Giao diện nhiệt giữa CPU, GPU và khối tản nhiệt</li><li>Mô-đun IGBT, thyristor trong biến tần, máy hàn, bộ lưu điện</li><li>Đế chip LED công suất và driver đèn chiếu sáng</li><li>Transistor, diode công suất trong bộ nguồn xung</li><li>Bộ điều khiển và bộ sạc trên ô tô điện</li></ul><h3>Ưu điểm</h3><ol><li>Độ xuyên kim phù hợp cho in lụa và máy định lượng tự động</li><li>Không đóng rắn, dễ tháo lắp khi bảo trì và thay linh kiện</li><li>Ít tách dầu, không làm bẩn bo mạch và linh kiện xung quanh</li><li>Cách điện tốt, an toàn khi tiếp xúc với chân linh kiện</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ dẫn nhiệt</td><td>0,9 W/m·K</td></tr><tr><td>Trọng lượng riêng (25 °C)</td><td>2,65</td></tr><tr><td>Độ xuyên kim</td><td>335</td></tr><tr><td>Độ tách dầu (150 °C, 24 giờ)</td><td>0,01%</td></tr><tr><td>Điện áp đánh thủng</td><td>4,0 kV/0,25 mm</td></tr><tr><td>Nhiệt độ làm việc</td><td>-50 đến 200 °C</td></tr></table><h4>Lưu ý khi thi công</h4><p>Lau sạch bề mặt linh kiện và tản nhiệt bằng cồn isopropyl trước khi bôi. Bôi lớp mỏng và đều, khoảng 50–100 µm; lớp mỡ quá dày sẽ làm tăng trở nhiệt. Siết vít đều theo đường chéo với lực siết khuyến nghị của nhà sản xuất linh kiện để mỡ dàn đều và đẩy hết bọt khí ra ngoài.</p><blockquote>Dùng khuôn in lụa hoặc stencil theo kích thước đế mô-đun giúp lớp mỡ đồng đều giữa các sản phẩm và tiết kiệm vật tư.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn quy cách đóng gói tuýp, can và giải pháp định lượng tự động.</p>','<p><strong>Shin-Etsu G-747 Thermal Grease</strong> is a one-component, non-curing thermally conductive silicone grease used to fill microscopic gaps between the base of power components and heat sinks. Thanks to its stable silicone base oil and evenly dispersed metal oxide filler, G-747 forms a thin interface layer with low thermal resistance and maintains stable properties over the long term, with minimal oil bleed and no drying out.</p><h3>Typical Applications</h3><ul><li>Thermal interface between CPUs, GPUs and heat sinks</li><li>IGBT and thyristor modules in inverters, welding machines and UPS systems</li><li>High-power LED chip bases and lighting drivers</li><li>Power transistors and diodes in switch-mode power supplies</li><li>Controllers and chargers in electric vehicles</li></ul><h3>Advantages</h3><ol><li>Penetration suited to screen printing and automatic dispensing equipment</li><li>Non-curing, making disassembly easy for maintenance and component replacement</li><li>Low oil bleed, does not contaminate the board or surrounding components</li><li>Good electrical insulation, safe in contact with component leads</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Thermal conductivity</td><td>0.9 W/m·K</td></tr><tr><td>Specific gravity (25 °C)</td><td>2.65</td></tr><tr><td>Penetration</td><td>335</td></tr><tr><td>Oil bleed (150 °C, 24 hours)</td><td>0.01%</td></tr><tr><td>Breakdown voltage</td><td>4.0 kV/0.25 mm</td></tr><tr><td>Service temperature</td><td>-50 to 200 °C</td></tr></table><h4>Application Notes</h4><p>Clean the component and heat sink surfaces with isopropyl alcohol before applying. Apply a thin, even layer of about 50–100 µm; an overly thick layer increases thermal resistance. Tighten screws evenly in a diagonal pattern to the component manufacturer\'s recommended torque so the grease spreads uniformly and all air bubbles are expelled.</p><blockquote>Using a screen or stencil sized to the module base ensures a consistent grease layer from part to part and saves material.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on tube and pail packaging and automatic dispensing solutions.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Mỡ dẫn nhiệt</td></tr><tr><td>Thương hiệu</td><td>Shin-Etsu</td></tr><tr><td>Gốc hóa học</td><td>Dầu silicone độn oxit kim loại</td></tr><tr><td>Màu sắc</td><td>Trắng</td></tr><tr><td>Số thành phần</td><td>1, không đóng rắn</td></tr><tr><td>Độ dẫn nhiệt</td><td>0,9 W/m·K</td></tr><tr><td>Trọng lượng riêng</td><td>2,65 ở 25 °C</td></tr><tr><td>Độ xuyên kim</td><td>335</td></tr><tr><td>Độ tách dầu</td><td>0,01% (150 °C, 24 giờ)</td></tr><tr><td>Điện áp đánh thủng</td><td>4,0 kV/0,25 mm</td></tr><tr><td>Điện trở suất khối</td><td>1×10¹⁴ Ω·cm</td></tr><tr><td>Nhiệt độ tối đa</td><td>200 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-50 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Thermal grease</td></tr><tr><td>Brand</td><td>Shin-Etsu</td></tr><tr><td>Chemistry</td><td>Silicone oil filled with metal oxide</td></tr><tr><td>Color</td><td>White</td></tr><tr><td>Components</td><td>1, non-curing</td></tr><tr><td>Thermal conductivity</td><td>0.9 W/m·K</td></tr><tr><td>Specific gravity</td><td>2.65 at 25 °C</td></tr><tr><td>Penetration</td><td>335</td></tr><tr><td>Oil bleed</td><td>0.01% (150 °C, 24 hours)</td></tr><tr><td>Breakdown voltage</td><td>4.0 kV/0.25 mm</td></tr><tr><td>Volume resistivity</td><td>1×10¹⁴ Ω·cm</td></tr><tr><td>Maximum temperature</td><td>200 °C</td></tr><tr><td>Minimum temperature</td><td>-50 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Truyền nhiệt giữa CPU, mô-đun công suất IGBT, đèn LED, bộ nguồn, điện tử ô tô và tản nhiệt; thi công bằng in lụa hoặc máy định lượng</p><h4>Đặc tính</h4><p>Dẫn nhiệt 0,9 W/m·K / Trọng lượng riêng 2,65 / Độ xuyên kim 335 / Làm việc -50 đến 200 °C / Không đóng rắn, ít tách dầu</p><h4>Bảo quản</h4><p>Nơi khô mát, tránh nắng trực tiếp, đậy kín sau khi dùng</p>','<h4>Applications</h4><p>Transfers heat from CPUs, IGBT power modules, LEDs, power supplies and automotive electronics to heat sinks; screen printed or dispensed</p><h4>Properties</h4><p>Conductivity 0.9 W/m·K / Specific gravity 2.65 / Penetration 335 / Service -50 to 200 °C / Non-curing, low oil bleed</p><h4>Storage</h4><p>Cool, dry place away from sunlight, reseal after use</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,20,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(512,NULL,1057,'uploads/images/ams/sp-g40m.jpg',NULL,'uploads/images/ams/loai-greases-and-oil-compounds.jpg','<p><strong>Shin-Etsu Mỡ silicone G-40M</strong> là mỡ bôi trơn gốc dầu silicone, được phát triển cho các cặp ma sát có chi tiết nhựa, nơi mỡ gốc khoáng có thể gây nứt ứng suất hoặc trương nở vật liệu. Độ đặc ổn định từ nhiệt độ âm đến 200 °C giúp G-40M duy trì màng bôi trơn tin cậy cho các cơ cấu đặt gần động cơ, cuộn sấy và linh kiện phát nhiệt.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Bánh răng nhựa POM, PA trong máy in, thiết bị văn phòng</li><li>Cơ cấu trượt, bản lề và khóa trong thiết bị gia dụng</li><li>Công tắc, núm xoay và chiết áp trong thiết bị điện</li><li>Trục, bạc trượt gần cuộn sấy, bộ gia nhiệt</li><li>Vòng đệm O-ring và van nhựa cần bôi trơn khi lắp</li></ul><h3>Ưu điểm</h3><ol><li>Tương thích với hầu hết nhựa kỹ thuật, không gây nứt ứng suất</li><li>Giữ độ đặc trong dải nhiệt rộng, không chảy khi nóng, không cứng khi lạnh</li><li>Bay hơi thấp, tuổi thọ bôi trơn dài, giảm chu kỳ bảo dưỡng</li><li>Kháng nước và oxy hóa, giảm tiếng ồn ma sát</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ xuyên kim</td><td>260–290</td></tr><tr><td>Trọng lượng riêng (25 °C)</td><td>1,02</td></tr><tr><td>Độ tách dầu (150 °C, 24 giờ)</td><td>0,3%</td></tr><tr><td>Độ bay hơi (150 °C, 24 giờ)</td><td>dưới 1%</td></tr><tr><td>Nhiệt độ làm việc</td><td>-40 đến 200 °C</td></tr></table><h4>Lưu ý khi thi công</h4><p>Làm sạch mỡ cũ và bụi bẩn trên chi tiết trước khi bôi. Chỉ bôi lượng vừa đủ để tạo màng mỏng trên bề mặt ma sát; bôi thừa dễ bám bụi và lan sang tiếp điểm điện. Không trộn lẫn với mỡ gốc khoáng hoặc mỡ tổng hợp khác. Silicone có thể ảnh hưởng đến khả năng bám của sơn và keo, nên cách ly khu vực bôi mỡ với khu vực sơn, dán.</p><blockquote>Với cặp kim loại – kim loại chịu tải nặng, mỡ silicone không phải lựa chọn tối ưu; G-40M phát huy tốt nhất khi có ít nhất một bề mặt là nhựa.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn quy cách tuýp, hũ và thiết bị bôi mỡ định lượng cho dây chuyền.</p>','<p><strong>Shin-Etsu G-40M Silicone Grease</strong> is a silicone oil-based lubricating grease developed for friction pairs involving plastic parts, where mineral-based greases can cause stress cracking or swelling. Its stable consistency from sub-zero temperatures up to 200 °C allows G-40M to maintain a reliable lubricating film for mechanisms located near motors, heating coils and heat-generating components.</p><h3>Typical Applications</h3><ul><li>POM and PA plastic gears in printers and office equipment</li><li>Sliding mechanisms, hinges and latches in household appliances</li><li>Switches, knobs and potentiometers in electrical equipment</li><li>Shafts and bushings near heating coils and heaters</li><li>O-rings and plastic valves that require lubrication during assembly</li></ul><h3>Advantages</h3><ol><li>Compatible with most engineering plastics, does not cause stress cracking</li><li>Maintains consistency over a wide temperature range, does not run when hot or stiffen when cold</li><li>Low volatility and long lubrication life, reducing maintenance intervals</li><li>Water and oxidation resistant, reduces friction noise</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Penetration</td><td>260–290</td></tr><tr><td>Specific gravity (25 °C)</td><td>1.02</td></tr><tr><td>Oil bleed (150 °C, 24 hours)</td><td>0.3%</td></tr><tr><td>Evaporation loss (150 °C, 24 hours)</td><td>below 1%</td></tr><tr><td>Service temperature</td><td>-40 to 200 °C</td></tr></table><h4>Application Notes</h4><p>Remove old grease and dirt from parts before applying. Apply just enough to form a thin film on the friction surfaces; excess grease attracts dust and can migrate onto electrical contacts. Do not mix with mineral-based or other synthetic greases. Silicone can affect the adhesion of paints and adhesives, so keep greasing areas separate from painting and bonding areas.</p><blockquote>For heavily loaded metal-to-metal pairs, silicone grease is not the optimal choice; G-40M performs best when at least one surface is plastic.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on tube and jar packaging and metered greasing equipment for your production line.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Mỡ bôi trơn silicone</td></tr><tr><td>Thương hiệu</td><td>Shin-Etsu</td></tr><tr><td>Gốc hóa học</td><td>Dầu nền silicone, chất làm đặc gốc xà phòng kim loại</td></tr><tr><td>Màu sắc</td><td>Trắng</td></tr><tr><td>Số thành phần</td><td>1</td></tr><tr><td>Độ xuyên kim</td><td>260–290</td></tr><tr><td>Trọng lượng riêng</td><td>1,02 ở 25 °C</td></tr><tr><td>Độ tách dầu</td><td>0,3% (150 °C, 24 giờ)</td></tr><tr><td>Độ bay hơi</td><td>dưới 1% (150 °C, 24 giờ)</td></tr><tr><td>Tương thích vật liệu</td><td>POM, PA, PC, ABS, PBT, cao su</td></tr><tr><td>Nhiệt độ tối đa</td><td>200 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-40 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Silicone lubricating grease</td></tr><tr><td>Brand</td><td>Shin-Etsu</td></tr><tr><td>Chemistry</td><td>Silicone base oil, metal soap thickener</td></tr><tr><td>Color</td><td>White</td></tr><tr><td>Components</td><td>1</td></tr><tr><td>Penetration</td><td>260–290</td></tr><tr><td>Specific gravity</td><td>1.02 at 25 °C</td></tr><tr><td>Oil bleed</td><td>0.3% (150 °C, 24 hours)</td></tr><tr><td>Evaporation loss</td><td>below 1% (150 °C, 24 hours)</td></tr><tr><td>Material compatibility</td><td>POM, PA, PC, ABS, PBT, rubber</td></tr><tr><td>Maximum temperature</td><td>200 °C</td></tr><tr><td>Minimum temperature</td><td>-40 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Bôi trơn cặp ma sát nhựa – kim loại, nhựa – nhựa trong bánh răng, trục trượt, cơ cấu khóa, công tắc, van và chi tiết gần nguồn nhiệt</p><h4>Đặc tính</h4><p>Độ xuyên kim 260–290 / Trọng lượng riêng 1,02 / Tách dầu 0,3% / Bay hơi dưới 1% / Làm việc -40 đến 200 °C, không hại nhựa</p><h4>Bảo quản</h4><p>Nơi khô mát, đậy kín nắp sau khi dùng để tránh bụi</p>','<h4>Applications</h4><p>Lubricates plastic-to-metal and plastic-to-plastic contacts in gears, slides, lock mechanisms, switches, valves and parts near heat sources</p><h4>Properties</h4><p>Penetration 260–290 / Specific gravity 1.02 / Oil separation 0.3% / Volatility under 1% / Service -40 to 200 °C, plastic safe</p><h4>Storage</h4><p>Cool, dry place, close the lid after use to keep out dust</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,20,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(513,NULL,1058,'uploads/images/ams/loai-silicone-fluids.jpg',NULL,'uploads/images/ams/loai-modified-silicone-fluids.jpg','<p><strong>Shin-Etsu Dầu silicone KF-96</strong> là dầu dimethyl polysiloxane tinh khiết, được cung cấp ở dải độ nhớt rất rộng từ dạng lỏng như nước đến dạng sệt như mật. Đặc tính cách điện cao, độ nhớt ít thay đổi theo nhiệt độ và tính trơ hóa học khiến KF-96 trở thành dầu silicone đa dụng bậc nhất trong công nghiệp điện, điện tử và hóa chất.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Dầu cách điện, dầu tẩm cho tụ điện và biến áp nhỏ</li><li>Dầu truyền nhiệt cho bể ổn nhiệt và thiết bị gia nhiệt</li><li>Dầu giảm chấn cho đồng hồ đo, giảm chấn quay</li><li>Chất chống tạo bọt trong sơn, mực in và xử lý nước thải</li><li>Chất tách khuôn cho cao su, nhựa và đúc kim loại</li></ul><h3>Đặc điểm nổi bật</h3><ol><li>Độ nhớt ít phụ thuộc nhiệt độ, vận hành ổn định từ -50 °C đến 200 °C</li><li>Cách điện tốt, tổn hao điện môi thấp</li><li>Trơ hóa học, không ăn mòn kim loại, không độc</li><li>Sức căng bề mặt thấp, dễ lan và tạo màng chống dính</li></ol><h3>Thông số chính (cấp 100 mm²/s)</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ nhớt động học (25 °C)</td><td>100 mm²/s</td></tr><tr><td>Trọng lượng riêng (25 °C)</td><td>0,97</td></tr><tr><td>Chiết suất</td><td>1,403</td></tr><tr><td>Điểm chớp cháy</td><td>trên 300 °C</td></tr><tr><td>Điện áp đánh thủng</td><td>50 kV/2,5 mm</td></tr><tr><td>Hằng số điện môi (50 Hz)</td><td>2,74</td></tr></table><h4>Lưu ý khi thi công</h4><p>Dầu silicone lan rất mạnh trên bề mặt; cần kiểm soát khu vực sử dụng vì dầu bám lên chi tiết sẽ làm giảm khả năng bám của sơn, keo và mực in. Với ứng dụng cách điện, nên sấy chân không để khử ẩm và khí hòa tan trước khi nạp dầu. Không để dầu tiếp xúc lâu với không khí ẩm ở nhiệt độ cao.</p><blockquote>Chọn cấp độ nhớt thấp cho chống tạo bọt và tách khuôn, cấp độ nhớt cao cho giảm chấn và bôi trơn chậm.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn chọn cấp độ nhớt và quy cách đóng gói can, phuy.</p>','<p><strong>Shin-Etsu KF-96 Silicone Fluid</strong> is a pure dimethyl polysiloxane fluid supplied in a very wide viscosity range, from water-thin to honey-thick. High electrical insulation, minimal viscosity change with temperature and chemical inertness make KF-96 one of the most versatile silicone fluids in the electrical, electronics and chemical industries.</p><h3>Typical Applications</h3><ul><li>Insulating and impregnating fluid for capacitors and small transformers</li><li>Heat transfer fluid for constant-temperature baths and heating equipment</li><li>Damping fluid for gauges and rotary dampers</li><li>Defoamer in paints, printing inks and wastewater treatment</li><li>Release agent for rubber, plastics and metal casting</li></ul><h3>Key Features</h3><ol><li>Viscosity is largely independent of temperature, with stable performance from -50 °C to 200 °C</li><li>Good electrical insulation and low dielectric loss</li><li>Chemically inert, non-corrosive to metals and non-toxic</li><li>Low surface tension, spreads easily to form a release film</li></ol><h3>Key Specifications (100 mm²/s grade)</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Kinematic viscosity (25 °C)</td><td>100 mm²/s</td></tr><tr><td>Specific gravity (25 °C)</td><td>0.97</td></tr><tr><td>Refractive index</td><td>1.403</td></tr><tr><td>Flash point</td><td>above 300 °C</td></tr><tr><td>Breakdown voltage</td><td>50 kV/2.5 mm</td></tr><tr><td>Dielectric constant (50 Hz)</td><td>2.74</td></tr></table><h4>Application Notes</h4><p>Silicone fluid spreads very readily over surfaces; control the area of use, since fluid on parts will reduce the adhesion of paints, adhesives and inks. For insulating applications, vacuum-dry the fluid to remove moisture and dissolved gases before filling. Do not expose the fluid to humid air at high temperatures for extended periods.</p><blockquote>Choose low-viscosity grades for defoaming and mold release, and high-viscosity grades for damping and slow-speed lubrication.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on viscosity grade selection and pail and drum packaging.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Dầu silicone</td></tr><tr><td>Thương hiệu</td><td>Shin-Etsu</td></tr><tr><td>Gốc hóa học</td><td>Dimethyl polysiloxane</td></tr><tr><td>Màu sắc</td><td>Trong suốt, không màu</td></tr><tr><td>Số thành phần</td><td>1</td></tr><tr><td>Dải độ nhớt</td><td>0,65–1.000.000 mm²/s</td></tr><tr><td>Trọng lượng riêng</td><td>0,97 (cấp 100 mm²/s)</td></tr><tr><td>Chiết suất</td><td>1,403</td></tr><tr><td>Điểm chớp cháy</td><td>trên 300 °C (cấp 100 mm²/s)</td></tr><tr><td>Điện áp đánh thủng</td><td>50 kV/2,5 mm</td></tr><tr><td>Hằng số điện môi</td><td>2,74 ở 50 Hz</td></tr><tr><td>Nhiệt độ tối đa</td><td>200 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-50 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Silicone fluid</td></tr><tr><td>Brand</td><td>Shin-Etsu</td></tr><tr><td>Chemistry</td><td>Dimethyl polysiloxane</td></tr><tr><td>Color</td><td>Clear, colorless</td></tr><tr><td>Components</td><td>1</td></tr><tr><td>Viscosity range</td><td>0.65–1,000,000 mm²/s</td></tr><tr><td>Specific gravity</td><td>0.97 (100 mm²/s grade)</td></tr><tr><td>Refractive index</td><td>1.403</td></tr><tr><td>Flash point</td><td>above 300 °C (100 mm²/s grade)</td></tr><tr><td>Breakdown voltage</td><td>50 kV/2.5 mm</td></tr><tr><td>Dielectric constant</td><td>2.74 at 50 Hz</td></tr><tr><td>Maximum temperature</td><td>200 °C</td></tr><tr><td>Minimum temperature</td><td>-50 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Dầu cách điện cho tụ điện, biến áp nhỏ; dầu truyền nhiệt, giảm chấn; chất chống bọt, tách khuôn, phụ gia làm bóng cho sơn và nhựa</p><h4>Đặc tính</h4><p>Độ nhớt 0,65–1.000.000 mm²/s / Trọng lượng riêng 0,97 / Đánh thủng 50 kV/2,5 mm / Chớp cháy trên 300 °C / Trơ hóa học</p><h4>Bảo quản</h4><p>Thùng kín, nơi khô mát, tránh lẫn nước và tạp chất</p>','<h4>Applications</h4><p>Dielectric fluid for capacitors and small transformers; heat transfer and damping fluid; antifoam, mold release and gloss additive for coatings</p><h4>Properties</h4><p>Viscosity 0.65–1,000,000 mm²/s / Specific gravity 0.97 / Breakdown 50 kV/2.5 mm / Flash point over 300 °C / Chemically inert</p><h4>Storage</h4><p>Sealed drums in a cool, dry place, keep free of water</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,20,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(514,NULL,1059,'uploads/images/ams/loai-silicone-resins.jpg',NULL,'uploads/images/ams/loai-silicone-fluids.jpg','<p><strong>Shin-Etsu Nhựa silicone KR series</strong> là dòng nhựa silicone liên kết mạng, dùng làm chất tạo màng chính hoặc chất biến tính cho sơn chịu nhiệt và vecni cách điện. Sau khi đóng rắn, nhựa tạo màng cứng có khung Si-O bền nhiệt, giữ được độ bám và tính cách điện ở nhiệt độ mà nhựa hữu cơ thông thường đã bị phân hủy.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Sơn chịu nhiệt cho ống xả, lò nung, lò sấy và bếp công nghiệp</li><li>Vecni tẩm cách điện cho cuộn dây động cơ, biến áp cấp H</li><li>Chất kết dính cho tấm mica, vật liệu cách nhiệt và composite</li><li>Lớp phủ chống dính, chịu nhiệt cho khuôn và dụng cụ nướng</li><li>Biến tính nhựa alkyd, polyester tăng độ bền thời tiết</li></ul><h3>Ưu điểm</h3><ol><li>Chịu nhiệt liên tục 250 °C, ngắn hạn cao hơn khi phối với bột nhôm</li><li>Cách điện tốt và ổn định ở nhiệt độ cao, độ hút ẩm thấp</li><li>Bền thời tiết, giữ màu và độ bóng, ít phấn hóa</li><li>Tương thích với nhiều nhựa hữu cơ để điều chỉnh tính chất màng</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Hàm lượng rắn</td><td>50%</td></tr><tr><td>Độ nhớt (25 °C)</td><td>50–200 mPa·s</td></tr><tr><td>Điều kiện đóng rắn</td><td>200 °C trong 1 giờ</td></tr><tr><td>Độ cứng màng</td><td>2H–4H (bút chì)</td></tr><tr><td>Độ bền điện môi màng</td><td>khoảng 50 kV/mm</td></tr></table><h4>Lưu ý khi thi công</h4><p>Pha loãng bằng xylene hoặc toluene đến độ nhớt phù hợp phương pháp phun, nhúng hoặc quét. Bề mặt kim loại cần phun cát hoặc tẩy dầu kỹ. Màng sơn cần sấy bay hơi dung môi ở nhiệt độ thấp trước khi nâng lên nhiệt độ đóng rắn để tránh rỗ khí. Thi công trong khu vực thông gió tốt, trang bị bảo hộ hô hấp.</p><blockquote>Chiều dày màng khô 20–30 µm cho mỗi lớp là tối ưu; màng quá dày dễ nứt khi chịu chu kỳ nhiệt.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn công thức phối sơn, mẫu thử và quy cách đóng gói.</p>','<p><strong>Shin-Etsu KR Series Silicone Resin</strong> is a range of cross-linking silicone resins used as the primary film former or as a modifier for heat-resistant paints and insulating varnishes. Once cured, the resin forms a hard film with a heat-stable Si-O backbone that retains adhesion and electrical insulation at temperatures where conventional organic resins would decompose.</p><h3>Typical Applications</h3><ul><li>Heat-resistant paints for exhaust pipes, kilns, drying ovens and industrial stoves</li><li>Insulating impregnation varnish for Class H motor and transformer windings</li><li>Binder for mica sheets, thermal insulation materials and composites</li><li>Heat-resistant non-stick coatings for molds and bakeware</li><li>Modifying alkyd and polyester resins to improve weather resistance</li></ul><h3>Advantages</h3><ol><li>Withstands 250 °C continuously, and higher short-term when formulated with aluminum powder</li><li>Good, stable electrical insulation at high temperatures, with low moisture absorption</li><li>Weather resistant, retains color and gloss with minimal chalking</li><li>Compatible with many organic resins to tailor film properties</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Solids content</td><td>50%</td></tr><tr><td>Viscosity (25 °C)</td><td>50–200 mPa·s</td></tr><tr><td>Cure conditions</td><td>200 °C for 1 hour</td></tr><tr><td>Film hardness</td><td>2H–4H (pencil)</td></tr><tr><td>Film dielectric strength</td><td>approx. 50 kV/mm</td></tr></table><h4>Application Notes</h4><p>Thin with xylene or toluene to a viscosity suited to spraying, dipping or brushing. Metal surfaces should be sandblasted or thoroughly degreased. Flash off the solvent at a low temperature before ramping up to the cure temperature to avoid pinholes. Apply in a well-ventilated area and wear respiratory protection.</p><blockquote>A dry film thickness of 20–30 µm per coat is optimal; overly thick films are prone to cracking under thermal cycling.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on paint formulation, samples and packaging options.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Nhựa silicone tạo màng</td></tr><tr><td>Thương hiệu</td><td>Shin-Etsu</td></tr><tr><td>Gốc hóa học</td><td>Nhựa methyl phenyl silicone trong dung môi</td></tr><tr><td>Màu sắc</td><td>Trong suốt không màu đến vàng nhạt</td></tr><tr><td>Số thành phần</td><td>1</td></tr><tr><td>Hàm lượng rắn</td><td>50%</td></tr><tr><td>Dung môi</td><td>Xylene, toluene</td></tr><tr><td>Độ nhớt</td><td>50–200 mPa·s ở 25 °C</td></tr><tr><td>Đóng rắn</td><td>200 °C trong 1 giờ</td></tr><tr><td>Độ cứng màng</td><td>2H–4H (bút chì)</td></tr><tr><td>Độ bền điện môi màng</td><td>khoảng 50 kV/mm</td></tr><tr><td>Nhiệt độ tối đa</td><td>250 °C liên tục</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-50 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Film-forming silicone resin</td></tr><tr><td>Brand</td><td>Shin-Etsu</td></tr><tr><td>Chemistry</td><td>Methyl phenyl silicone resin in solvent</td></tr><tr><td>Color</td><td>Clear colorless to pale yellow</td></tr><tr><td>Components</td><td>1</td></tr><tr><td>Solids content</td><td>50%</td></tr><tr><td>Solvent</td><td>Xylene, toluene</td></tr><tr><td>Viscosity</td><td>50–200 mPa·s at 25 °C</td></tr><tr><td>Cure</td><td>200 °C for 1 hour</td></tr><tr><td>Film hardness</td><td>2H–4H (pencil)</td></tr><tr><td>Film dielectric strength</td><td>approx. 50 kV/mm</td></tr><tr><td>Maximum temperature</td><td>250 °C continuous</td></tr><tr><td>Minimum temperature</td><td>-50 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Chất tạo màng cho sơn chịu nhiệt ống xả, lò sấy, bếp công nghiệp; vecni cách điện cho cuộn dây, tấm mica và composite chịu nhiệt</p><h4>Đặc tính</h4><p>Hàm lượng rắn 50% / Độ nhớt 50–200 mPa·s / Đóng rắn 200 °C trong 1 giờ / Chịu nhiệt liên tục 250 °C / Độ cứng màng 2H–4H</p><h4>Bảo quản</h4><p>Thùng kín, nơi thoáng mát, xa nguồn lửa</p>','<h4>Applications</h4><p>Binder for heat-resistant coatings on exhausts, ovens and cookers; insulating varnish for coils, mica sheet and composites</p><h4>Properties</h4><p>Solids 50% / Viscosity 50–200 mPa·s / Cure 1 h at 200 °C / Continuous heat resistance 250 °C / Film hardness 2H–4H</p><h4>Storage</h4><p>Sealed containers in a cool, ventilated area, away from flames</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,20,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(515,NULL,1060,'uploads/images/ams/loai-rubber-compounds.jpg',NULL,'uploads/images/ams/loai-one-component-liquid-rubbers.jpg','<p><strong>Shin-Etsu Cao su silicone KE series</strong> là dòng cao su silicone rắn lưu hóa nhiệt độ cao (HTV), được phối trộn sẵn chất độn gia cường để nhà sản xuất chỉ cần thêm chất lưu hóa và gia công. Dòng sản phẩm có nhiều cấp độ cứng và tính năng đặc biệt như chịu dầu, chống cháy, dẫn điện, đáp ứng đa dạng yêu cầu chế tạo linh kiện cao su kỹ thuật.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Gioăng, phớt, ống dẫn khí và nước làm mát trên ô tô</li><li>Bàn phím, nút bấm cao su cho thiết bị điện tử</li><li>Gioăng cửa lò, nồi cơm điện và thiết bị gia nhiệt</li><li>Vỏ bọc cáp chịu nhiệt, ống co cách điện</li><li>Linh kiện tiếp xúc thực phẩm như núm, van, gioăng nắp</li></ul><h3>Ưu điểm</h3><ol><li>Giữ đàn hồi từ -50 °C đến 200 °C, biến dạng dư khi nén thấp</li><li>Cách điện tốt, bền ozone, tia UV và thời tiết</li><li>Phối trộn sẵn, chất lượng đồng đều theo lô, dễ pha màu</li><li>Phù hợp ép khuôn, ép phun, đùn và cán tấm</li></ol><h3>Quy trình gia công khuyến nghị</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ cứng</td><td>30–80 Shore A</td></tr><tr><td>Độ bền kéo</td><td>7–10 MPa</td></tr><tr><td>Độ giãn dài khi đứt</td><td>300–600%</td></tr><tr><td>Lưu hóa sơ cấp</td><td>170 °C trong 10 phút</td></tr><tr><td>Lưu hóa thứ cấp</td><td>200 °C trong 4 giờ</td></tr></table><h4>Lưu ý khi thi công</h4><p>Cán luyện lại trên máy cán hai trục trước khi gia công để phục hồi độ dẻo, sau đó thêm chất lưu hóa peroxide theo tỷ lệ khuyến nghị. Tránh nhiễm bẩn từ cao su hữu cơ, lưu huỳnh hoặc amine vì có thể gây ức chế lưu hóa. Lưu hóa thứ cấp giúp loại bỏ sản phẩm phân hủy của peroxide, giảm mùi và cải thiện biến dạng dư khi nén.</p><blockquote>Vệ sinh kỹ máy cán và khuôn khi chuyển từ cao su hữu cơ sang silicone để tránh hiện tượng bề mặt dính, lưu hóa không hết.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn chọn cấp độ cứng, chất lưu hóa và chạy thử trên khuôn thực tế.</p>','<p><strong>Shin-Etsu KE Series Silicone Rubber</strong> is a range of high-temperature vulcanizing (HTV) solid silicone rubbers pre-compounded with reinforcing fillers, so manufacturers only need to add a curing agent and process. The range offers multiple hardness grades and specialty properties such as oil resistance, flame retardancy and electrical conductivity, meeting diverse requirements for engineered rubber components.</p><h3>Typical Applications</h3><ul><li>Gaskets, seals, air hoses and coolant hoses in automobiles</li><li>Rubber keypads and buttons for electronic devices</li><li>Door gaskets for ovens, rice cookers and heating appliances</li><li>Heat-resistant cable jackets and insulating sleeves</li><li>Food-contact parts such as nipples, valves and lid gaskets</li></ul><h3>Advantages</h3><ol><li>Remains elastic from -50 °C to 200 °C with low compression set</li><li>Good electrical insulation, resistant to ozone, UV and weathering</li><li>Pre-compounded for consistent lot-to-lot quality, easy to color</li><li>Suitable for compression molding, injection molding, extrusion and calendering</li></ol><h3>Properties and Recommended Processing</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Hardness</td><td>30–80 Shore A</td></tr><tr><td>Tensile strength</td><td>7–10 MPa</td></tr><tr><td>Elongation at break</td><td>300–600%</td></tr><tr><td>Press cure</td><td>170 °C for 10 minutes</td></tr><tr><td>Post-cure</td><td>200 °C for 4 hours</td></tr></table><h4>Application Notes</h4><p>Re-mill the compound on a two-roll mill before processing to restore plasticity, then add the peroxide curing agent at the recommended ratio. Avoid contamination from organic rubber, sulfur or amines, as these can inhibit cure. Post-curing removes peroxide decomposition by-products, reducing odor and improving compression set.</p><blockquote>Thoroughly clean mills and molds when switching from organic rubber to silicone to avoid tacky surfaces and incomplete cure.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on hardness grade and curing agent selection, and for trial runs on your actual molds.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Cao su silicone rắn lưu hóa nhiệt (HTV)</td></tr><tr><td>Thương hiệu</td><td>Shin-Etsu</td></tr><tr><td>Gốc hóa học</td><td>Polydimethylsiloxane gia cường silica</td></tr><tr><td>Màu sắc</td><td>Trong mờ, pha màu theo yêu cầu</td></tr><tr><td>Số thành phần</td><td>1 + chất lưu hóa peroxide</td></tr><tr><td>Độ cứng</td><td>30–80 Shore A</td></tr><tr><td>Trọng lượng riêng</td><td>1,10–1,25</td></tr><tr><td>Độ bền kéo</td><td>7–10 MPa</td></tr><tr><td>Độ giãn dài khi đứt</td><td>300–600%</td></tr><tr><td>Độ bền xé</td><td>15–35 kN/m</td></tr><tr><td>Biến dạng dư khi nén</td><td>10–20% (180 °C, 22 giờ)</td></tr><tr><td>Nhiệt độ tối đa</td><td>200 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-50 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Heat-cured solid silicone rubber (HTV)</td></tr><tr><td>Brand</td><td>Shin-Etsu</td></tr><tr><td>Chemistry</td><td>Silica-reinforced polydimethylsiloxane</td></tr><tr><td>Color</td><td>Translucent, custom colors on request</td></tr><tr><td>Components</td><td>1 + peroxide curing agent</td></tr><tr><td>Hardness</td><td>30–80 Shore A</td></tr><tr><td>Specific gravity</td><td>1.10–1.25</td></tr><tr><td>Tensile strength</td><td>7–10 MPa</td></tr><tr><td>Elongation at break</td><td>300–600%</td></tr><tr><td>Tear strength</td><td>15–35 kN/m</td></tr><tr><td>Compression set</td><td>10–20% (180 °C, 22 hours)</td></tr><tr><td>Maximum temperature</td><td>200 °C</td></tr><tr><td>Minimum temperature</td><td>-50 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Đúc ép, ép phun và đùn gioăng, phớt, ống, nút bấm và linh kiện cao su cho ô tô, thiết bị điện, thiết bị gia dụng và thực phẩm</p><h4>Đặc tính</h4><p>Độ cứng 30–80 Shore A / Bền kéo 7–10 MPa / Giãn dài 300–600% / Bền xé 15–35 kN/m / Làm việc -50 đến 200 °C, dễ pha màu</p><h4>Bảo quản</h4><p>Dưới 30 °C, tránh nắng, dùng trong 6 tháng từ ngày sản xuất</p>','<h4>Applications</h4><p>Compression molding, injection molding and extrusion of gaskets, seals, tubing, keypads and rubber parts for automotive, electrical and food use</p><h4>Properties</h4><p>Hardness 30–80 Shore A / Tensile 7–10 MPa / Elongation 300–600% / Tear 15–35 kN/m / Service -50 to 200 °C, easy to color</p><h4>Storage</h4><p>Below 30 °C, away from sunlight, use within 6 months</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,20,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(516,NULL,1061,'uploads/images/ams/loai-one-component-liquid-rubbers.jpg',NULL,'uploads/images/ams/loai-rubber-compounds.jpg','<p><strong>Shin-Etsu Cao su lỏng RTV một thành phần</strong> là keo silicone đóng rắn ở nhiệt độ phòng nhờ phản ứng với hơi ẩm trong không khí, tạo thành cao su đàn hồi bám chắc trên kim loại, kính, gốm và nhiều loại nhựa. Loại đóng rắn trung tính không sinh axit, an toàn cho đồng, mạch in và linh kiện điện tử nhạy cảm.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Cố định tụ điện, cuộn cảm, dây nối trên bo mạch chống rung</li><li>Trám kín vỏ đèn LED, hộp đấu dây, cảm biến ngoài trời</li><li>Tạo gioăng tại chỗ cho nắp hộp số, nắp máy, mặt bích</li><li>Kết dính kính, gốm trong thiết bị gia nhiệt và lò nướng</li><li>Bọc phủ đầu nối, mối hàn chống ẩm</li></ul><h3>Ưu điểm</h3><ol><li>Một thành phần, không cần trộn, thi công trực tiếp từ tuýp hoặc máy bơm</li><li>Đóng rắn trung tính, không ăn mòn kim loại và linh kiện</li><li>Giữ đàn hồi trong dải nhiệt rộng, hấp thụ rung và giãn nở nhiệt</li><li>Cách điện, chống ẩm, bền thời tiết và ozone</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Thời gian khô mặt (23 °C, 50% RH)</td><td>5–10 phút</td></tr><tr><td>Tốc độ đóng rắn sâu</td><td>khoảng 3 mm/24 giờ</td></tr><tr><td>Độ cứng</td><td>30–40 Shore A</td></tr><tr><td>Độ bền kéo</td><td>2,5 MPa</td></tr><tr><td>Độ giãn dài khi đứt</td><td>300%</td></tr></table><h4>Lưu ý khi thi công</h4><p>Bề mặt cần sạch, khô, không dầu mỡ; với nhựa khó bám nên dùng thêm primer. Do đóng rắn bằng ẩm từ bề mặt vào trong, không nên trám lớp dày quá 6 mm hoặc trong khe kín hoàn toàn. Độ ẩm thấp làm chậm đóng rắn. Đợi tối thiểu 24 giờ trước khi chịu tải cơ học và 72 giờ trước khi thử kín nước.</p><blockquote>Với thiết bị có rơ le hoặc tiếp điểm hở, chọn loại RTV ít bay hơi siloxane thấp phân tử để tránh hiện tượng tiếp xúc kém về lâu dài.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn chọn loại đóng rắn, màu sắc và quy cách tuýp, ống, thùng.</p>','<p><strong>Shin-Etsu One-Component RTV Silicone Rubber</strong> is a silicone sealant that cures at room temperature by reacting with atmospheric moisture, forming an elastic rubber that bonds firmly to metal, glass, ceramics and many plastics. The neutral-cure type releases no acid, making it safe for copper, printed circuits and sensitive electronic components.</p><h3>Typical Applications</h3><ul><li>Staking capacitors, inductors and wires on circuit boards against vibration</li><li>Sealing LED light housings, junction boxes and outdoor sensors</li><li>Formed-in-place gaskets for gearbox covers, engine covers and flanges</li><li>Bonding glass and ceramics in heating appliances and ovens</li><li>Encapsulating connectors and solder joints against moisture</li></ul><h3>Advantages</h3><ol><li>One-component, no mixing required, applied directly from tube or pump</li><li>Neutral cure, non-corrosive to metals and components</li><li>Remains elastic over a wide temperature range, absorbing vibration and thermal expansion</li><li>Electrically insulating, moisture proof, resistant to weathering and ozone</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Tack-free time (23 °C, 50% RH)</td><td>5–10 minutes</td></tr><tr><td>Depth of cure</td><td>approx. 3 mm/24 hours</td></tr><tr><td>Hardness</td><td>30–40 Shore A</td></tr><tr><td>Tensile strength</td><td>2.5 MPa</td></tr><tr><td>Elongation at break</td><td>300%</td></tr></table><h4>Application Notes</h4><p>Surfaces must be clean, dry and free of oil and grease; use a primer on hard-to-bond plastics. Because it cures by moisture from the surface inward, do not apply in layers thicker than 6 mm or in fully enclosed gaps. Low humidity slows curing. Wait at least 24 hours before applying mechanical loads and 72 hours before water-tightness testing.</p><blockquote>For equipment with relays or open contacts, choose a low-volatile RTV grade with reduced low-molecular-weight siloxane to avoid long-term contact failure.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on cure type, color and tube, cartridge and pail packaging.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Keo silicone RTV một thành phần</td></tr><tr><td>Thương hiệu</td><td>Shin-Etsu</td></tr><tr><td>Gốc hóa học</td><td>Silicone đóng rắn ngưng tụ, kiểu trung tính</td></tr><tr><td>Màu sắc</td><td>Trắng, đen, xám, trong mờ</td></tr><tr><td>Số thành phần</td><td>1</td></tr><tr><td>Thời gian khô mặt</td><td>5–10 phút</td></tr><tr><td>Độ cứng</td><td>30–40 Shore A</td></tr><tr><td>Độ bền kéo</td><td>2,5 MPa</td></tr><tr><td>Độ giãn dài khi đứt</td><td>300%</td></tr><tr><td>Độ bền điện môi</td><td>20 kV/mm</td></tr><tr><td>Điện trở suất khối</td><td>1×10¹⁵ Ω·cm</td></tr><tr><td>Nhiệt độ tối đa</td><td>200 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-50 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH, UL 94 HB</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>One-component RTV silicone sealant</td></tr><tr><td>Brand</td><td>Shin-Etsu</td></tr><tr><td>Chemistry</td><td>Condensation-cure silicone, neutral type</td></tr><tr><td>Color</td><td>White, black, gray, translucent</td></tr><tr><td>Components</td><td>1</td></tr><tr><td>Tack-free time</td><td>5–10 minutes</td></tr><tr><td>Hardness</td><td>30–40 Shore A</td></tr><tr><td>Tensile strength</td><td>2.5 MPa</td></tr><tr><td>Elongation at break</td><td>300%</td></tr><tr><td>Dielectric strength</td><td>20 kV/mm</td></tr><tr><td>Volume resistivity</td><td>1×10¹⁵ Ω·cm</td></tr><tr><td>Maximum temperature</td><td>200 °C</td></tr><tr><td>Minimum temperature</td><td>-50 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH, UL 94 HB</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Trám kín, kết dính và cố định linh kiện trên bo mạch; làm kín vỏ thiết bị, đèn LED, cảm biến; tạo gioăng tại chỗ cho nắp hộp và mặt bích</p><h4>Đặc tính</h4><p>Khô mặt 5–10 phút / Độ cứng 30–40 Shore A / Bền kéo 2,5 MPa / Bền điện môi 20 kV/mm / Làm việc -50 đến 200 °C, không ăn mòn</p><h4>Bảo quản</h4><p>Dưới 30 °C, đậy kín nắp ngay sau khi dùng</p>','<h4>Applications</h4><p>Seals, bonds and stakes components on circuit boards; seals housings, LED fixtures and sensors; forms gaskets in place on covers and flanges</p><h4>Properties</h4><p>Tack free 5–10 min / Hardness 30–40 Shore A / Tensile 2.5 MPa / Dielectric 20 kV/mm / Service -50 to 200 °C, non-corrosive</p><h4>Storage</h4><p>Below 30 °C, recap immediately after use</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,20,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(517,NULL,1062,'uploads/images/ams/loai-silanes.jpg',NULL,'uploads/images/ams/loai-silicone-resins.jpg','<p><strong>Shin-Etsu Silane KBM series</strong> là nhóm chất kết nối silane gốc methoxy, đóng vai trò cầu nối hóa học giữa bề mặt vô cơ như thủy tinh, kim loại, chất độn khoáng và polymer hữu cơ. Chỉ với một lượng nhỏ, silane cải thiện rõ rệt độ bám dính, cơ tính và khả năng chịu ẩm của composite, keo dán và lớp phủ.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Xử lý bề mặt sợi thủy tinh trong composite FRP và nhựa gia cường</li><li>Xử lý chất độn silica, talc, nhôm hydroxide cho cao su và nhựa</li><li>Phụ gia tăng bám cho keo epoxy, polyurethane và silicone</li><li>Thành phần primer cho kính, kim loại trước khi dán hoặc sơn</li><li>Biến tính nhựa, tạo liên kết ngang cho PE và nhựa acrylic</li></ul><h3>Hiệu quả mang lại</h3><ol><li>Tăng độ bám dính giữa nhựa nền và bề mặt vô cơ</li><li>Giữ cơ tính composite sau khi ngâm nước hoặc chịu ẩm nóng</li><li>Cải thiện độ phân tán chất độn, giảm độ nhớt hỗn hợp</li><li>Nhiều nhóm chức để chọn đúng theo hệ nhựa nền</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ tinh khiết</td><td>trên 97%</td></tr><tr><td>Trọng lượng riêng (25 °C)</td><td>1,0–1,1</td></tr><tr><td>Liều dùng xử lý chất độn</td><td>0,5–2% khối lượng</td></tr><tr><td>Liều dùng phụ gia trong keo</td><td>0,5–1% khối lượng</td></tr><tr><td>pH dung dịch thủy phân</td><td>4–5</td></tr></table><h4>Lưu ý khi thi công</h4><p>Chọn nhóm chức phù hợp với nhựa nền: epoxy silane cho epoxy và polyurethane, amino silane cho phenolic và polyamide, vinyl silane cho polyolefin, methacryloxy silane cho polyester không no và acrylic. Dung dịch thủy phân nên dùng trong ngày. Silane sinh methanol khi thủy phân, cần thao tác ở khu vực thông gió và đeo găng tay, kính bảo hộ.</p><blockquote>Thêm silane trực tiếp vào hỗn hợp nhựa (integral blend) đơn giản hơn tiền xử lý chất độn, nhưng tiền xử lý thường cho hiệu quả cao hơn với cùng liều dùng.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn chọn nhóm chức, phương pháp xử lý và quy cách đóng gói.</p>','<p><strong>Shin-Etsu KBM Series Silane</strong> is a family of methoxy-functional silane coupling agents that act as a chemical bridge between inorganic surfaces such as glass, metals and mineral fillers and organic polymers. In small amounts, silanes significantly improve the adhesion, mechanical properties and moisture resistance of composites, adhesives and coatings.</p><h3>Typical Applications</h3><ul><li>Surface treatment of glass fiber in FRP composites and reinforced plastics</li><li>Treatment of silica, talc and aluminum hydroxide fillers for rubber and plastics</li><li>Adhesion-promoting additive for epoxy, polyurethane and silicone adhesives</li><li>Primer component for glass and metal before bonding or painting</li><li>Resin modification and cross-linking of PE and acrylic resins</li></ul><h3>Benefits</h3><ol><li>Increases adhesion between the resin matrix and inorganic surfaces</li><li>Retains composite mechanical properties after water immersion or hot-humid exposure</li><li>Improves filler dispersion and lowers compound viscosity</li><li>Multiple functional groups to match the resin system</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Purity</td><td>above 97%</td></tr><tr><td>Specific gravity (25 °C)</td><td>1.0–1.1</td></tr><tr><td>Dosage for filler treatment</td><td>0.5–2 wt%</td></tr><tr><td>Dosage as adhesive additive</td><td>0.5–1 wt%</td></tr><tr><td>pH of hydrolysis solution</td><td>4–5</td></tr></table><h4>Application Notes</h4><p>Select the functional group to suit the resin matrix: epoxy silane for epoxy and polyurethane, amino silane for phenolic and polyamide, vinyl silane for polyolefins, and methacryloxy silane for unsaturated polyester and acrylics. Use hydrolyzed solutions within the same day. Silanes release methanol on hydrolysis, so handle in a ventilated area and wear gloves and safety glasses.</p><blockquote>Adding silane directly to the resin mix (integral blend) is simpler than pretreating the filler, but pretreatment usually delivers better results at the same dosage.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on functional group selection, treatment methods and packaging options.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Chất kết nối silane</td></tr><tr><td>Thương hiệu</td><td>Shin-Etsu</td></tr><tr><td>Gốc hóa học</td><td>Organo-functional methoxy silane</td></tr><tr><td>Nhóm chức</td><td>Epoxy, amino, vinyl, methacryloxy, mercapto</td></tr><tr><td>Màu sắc</td><td>Trong suốt, không màu</td></tr><tr><td>Số thành phần</td><td>1</td></tr><tr><td>Độ tinh khiết</td><td>trên 97%</td></tr><tr><td>Trọng lượng riêng</td><td>1,0–1,1 ở 25 °C</td></tr><tr><td>Liều dùng</td><td>0,5–2% khối lượng chất độn</td></tr><tr><td>pH thủy phân khuyến nghị</td><td>4–5</td></tr><tr><td>Sản phẩm phụ khi thủy phân</td><td>Methanol</td></tr><tr><td>Nhiệt độ bảo quản tối đa</td><td>30 °C</td></tr><tr><td>Nhiệt độ bảo quản tối thiểu</td><td>5 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Silane coupling agent</td></tr><tr><td>Brand</td><td>Shin-Etsu</td></tr><tr><td>Chemistry</td><td>Organo-functional methoxy silane</td></tr><tr><td>Functional groups</td><td>Epoxy, amino, vinyl, methacryloxy, mercapto</td></tr><tr><td>Color</td><td>Clear, colorless</td></tr><tr><td>Components</td><td>1</td></tr><tr><td>Purity</td><td>above 97%</td></tr><tr><td>Specific gravity</td><td>1.0–1.1 at 25 °C</td></tr><tr><td>Dosage</td><td>0.5–2% of filler weight</td></tr><tr><td>Recommended hydrolysis pH</td><td>4–5</td></tr><tr><td>Hydrolysis by-product</td><td>Methanol</td></tr><tr><td>Maximum storage temperature</td><td>30 °C</td></tr><tr><td>Minimum storage temperature</td><td>5 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Chất kết nối tăng bám dính giữa vật liệu vô cơ và hữu cơ; xử lý bề mặt chất độn silica, thủy tinh, talc; phụ gia primer cho keo, sơn</p><h4>Đặc tính</h4><p>Độ tinh khiết trên 97% / Trọng lượng riêng 1,0–1,1 / Liều dùng 0,5–2% khối lượng chất độn / Thủy phân ở pH 4–5 / Lỏng trong suốt</p><h4>Bảo quản</h4><p>Bao bì kín, tránh ẩm, nạp khí nitơ sau khi mở</p>','<h4>Applications</h4><p>Coupling agent that improves adhesion between inorganic and organic materials; treats silica, glass and talc fillers; primer additive for adhesives</p><h4>Properties</h4><p>Purity over 97% / Specific gravity 1.0–1.1 / Dosage 0.5–2% of filler weight / Hydrolyzes at pH 4–5 / Clear liquid</p><h4>Storage</h4><p>Sealed packaging, keep dry, blanket with nitrogen after opening</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,20,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(518,NULL,1063,'uploads/images/ams/sp-loctite411.jpg',NULL,'uploads/images/ams/cat-4.jpg','<p><strong>Henkel Keo dán Loctite 411</strong> là keo cyanoacrylate một thành phần được gia cường bằng cao su, khắc phục nhược điểm giòn của keo dán nhanh thông thường. Mối dán đóng rắn trong vài giây nhưng vẫn có độ dai, chịu bóc, va đập và rung động tốt, phù hợp cho các chi tiết cao su và nhựa phải làm việc trong điều kiện tải động.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Dán gioăng cao su, đệm EPDM, NBR lên khung kim loại</li><li>Nối đầu dây curoa, gioăng O-ring dạng dây</li><li>Dán nút bấm, chân đế cao su cho thiết bị điện tử</li><li>Lắp ráp chi tiết nhựa ABS, PC, PVC chịu va đập</li><li>Cố định nhanh chi tiết trên đồ gá lắp ráp</li></ul><h3>Ưu điểm</h3><ol><li>Định vị trong vài giây, tăng năng suất lắp ráp</li><li>Gia cường cao su, chịu bóc và va đập tốt hơn keo CA tiêu chuẩn</li><li>Dạng gel không chảy, thi công được trên bề mặt đứng</li><li>Bám tốt trên hầu hết cao su, nhựa và kim loại</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Thời gian định vị</td><td>5–20 giây</td></tr><tr><td>Thời gian đạt cường độ đầy đủ</td><td>24 giờ</td></tr><tr><td>Độ bền cắt trên thép</td><td>22 N/mm²</td></tr><tr><td>Khe hở điền đầy tối đa</td><td>0,2 mm</td></tr><tr><td>Nhiệt độ làm việc</td><td>-55 đến 120 °C</td></tr></table><h4>Lưu ý khi thi công</h4><p>Lau sạch bề mặt bằng cồn isopropyl, đợi khô hoàn toàn. Chỉ bôi lượng keo vừa đủ trên một bề mặt rồi ép hai chi tiết lại, giữ yên đến khi định vị. Keo dư dễ gây vết trắng do bay hơi monome; nên thông gió tốt quanh mối dán. Với vật liệu năng lượng bề mặt thấp như PP, PE cần dùng thêm primer chuyên dụng; với khe hở lớn có thể dùng chất hoạt hóa để tăng tốc đóng rắn.</p><blockquote>Keo CA đóng rắn nhờ ẩm: trong mùa hanh khô, độ ẩm xưởng thấp sẽ làm thời gian định vị dài hơn rõ rệt so với thông số danh định.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn quy cách chai, primer, chất hoạt hóa và thiết bị bơm keo định lượng.</p>','<p><strong>Henkel Loctite 411 Adhesive</strong> is a one-component, rubber-toughened cyanoacrylate that overcomes the brittleness of conventional instant adhesives. Bonds fixture in seconds yet remain tough, with good resistance to peel, impact and vibration, making it ideal for rubber and plastic parts operating under dynamic loads.</p><h3>Typical Applications</h3><ul><li>Bonding rubber gaskets and EPDM and NBR pads to metal frames</li><li>Splicing drive belts and O-ring cord</li><li>Bonding buttons and rubber feet on electronic devices</li><li>Assembling impact-resistant ABS, PC and PVC plastic parts</li><li>Quick fixturing of parts on assembly jigs</li></ul><h3>Advantages</h3><ol><li>Fixtures in seconds, increasing assembly productivity</li><li>Rubber-toughened for better peel and impact resistance than standard CA adhesives</li><li>Non-sag gel, can be applied on vertical surfaces</li><li>Bonds well to most rubbers, plastics and metals</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Fixture time</td><td>5–20 seconds</td></tr><tr><td>Time to full strength</td><td>24 hours</td></tr><tr><td>Shear strength on steel</td><td>22 N/mm²</td></tr><tr><td>Maximum gap fill</td><td>0.2 mm</td></tr><tr><td>Service temperature</td><td>-55 to 120 °C</td></tr></table><h4>Application Notes</h4><p>Clean surfaces with isopropyl alcohol and allow to dry completely. Apply just enough adhesive to one surface, then press the two parts together and hold still until fixtured. Excess adhesive can cause white blooming from monomer evaporation; ensure good ventilation around the bond. Low surface energy materials such as PP and PE require a dedicated primer; for larger gaps, an activator can be used to speed up curing.</p><blockquote>CA adhesives cure with moisture: in dry seasons, low workshop humidity will make fixture times noticeably longer than the nominal specification.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on bottle sizes, primers, activators and metered adhesive dispensing equipment.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Keo dán nhanh cyanoacrylate</td></tr><tr><td>Thương hiệu</td><td>Henkel (Loctite)</td></tr><tr><td>Gốc hóa học</td><td>Ethyl cyanoacrylate gia cường cao su</td></tr><tr><td>Màu sắc</td><td>Trong suốt</td></tr><tr><td>Số thành phần</td><td>1</td></tr><tr><td>Dạng</td><td>Gel thixotropic</td></tr><tr><td>Thời gian định vị</td><td>5–20 giây</td></tr><tr><td>Thời gian đóng rắn hoàn toàn</td><td>24 giờ</td></tr><tr><td>Độ bền cắt trên thép</td><td>22 N/mm²</td></tr><tr><td>Khe hở điền đầy tối đa</td><td>0,2 mm</td></tr><tr><td>Nhiệt độ tối đa</td><td>120 °C</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-55 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Cyanoacrylate instant adhesive</td></tr><tr><td>Brand</td><td>Henkel (Loctite)</td></tr><tr><td>Chemistry</td><td>Rubber-toughened ethyl cyanoacrylate</td></tr><tr><td>Color</td><td>Clear</td></tr><tr><td>Components</td><td>1</td></tr><tr><td>Form</td><td>Thixotropic gel</td></tr><tr><td>Fixture time</td><td>5–20 seconds</td></tr><tr><td>Full cure time</td><td>24 hours</td></tr><tr><td>Shear strength on steel</td><td>22 N/mm²</td></tr><tr><td>Maximum gap fill</td><td>0.2 mm</td></tr><tr><td>Maximum temperature</td><td>120 °C</td></tr><tr><td>Minimum temperature</td><td>-55 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Dán nhanh cao su, nhựa, kim loại cần chịu va đập và rung động: gioăng, nút bấm, dây curoa, vỏ thiết bị và đồ gá trên dây chuyền</p><h4>Đặc tính</h4><p>Định vị 5–20 giây / Bền cắt trên thép 22 N/mm² / Điền đầy khe 0,2 mm / Dạng gel thixotropic / Làm việc -55 đến 120 °C</p><h4>Bảo quản</h4><p>Chưa mở giữ ở 2–8 °C, để về nhiệt độ phòng trước khi mở</p>','<h4>Applications</h4><p>Fast bonding of rubber, plastics and metals exposed to impact and vibration: gaskets, keypads, belts, housings and production line fixtures</p><h4>Properties</h4><p>Fixture time 5–20 s / Shear strength on steel 22 N/mm² / Gap fill 0.2 mm / Thixotropic gel / Service range -55 to 120 °C</p><h4>Storage</h4><p>Unopened at 2–8 °C, warm to room temperature before opening</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,21,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(519,NULL,1064,'uploads/images/ams/loai-solder-paste.jpg',NULL,'uploads/images/ams/loai-solder-bar.jpg,uploads/images/ams/loai-flux-cored-wire.jpg','<p><strong>Fuji Chemical Kem hàn SMT</strong> là kem hàn không chì hợp kim SAC305, kết hợp bột hàn cầu hóa đồng đều và hệ chất trợ hàn no-clean thế hệ mới. Sản phẩm cho chất lượng in ổn định qua nhiều giờ trên stencil, khả năng thấm ướt tốt trên các lớp hoàn thiện bề mặt phổ biến và cặn trợ hàn an toàn, không cần rửa sau hàn.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Hàn reflow linh kiện chip 0201, 0402 và IC bước chân nhỏ</li><li>Hàn BGA, QFN, LGA trên bo mạch nhiều lớp</li><li>Sản xuất bo mạch điện tử tiêu dùng, điện thoại, thiết bị đeo</li><li>Bo mạch điều khiển ô tô và thiết bị công nghiệp</li><li>Mô-đun LED, bộ nguồn và thiết bị viễn thông</li></ul><h3>Ưu điểm</h3><ol><li>In ổn định đến 8 giờ trên stencil, độ nhớt ít thay đổi</li><li>Thấm ướt tốt trên OSP, ENIG, thiếc nhúng; ít đọng bi và cầu hàn</li><li>Giảm lỗ rỗng (void) dưới pad tản nhiệt của QFN</li><li>Cặn trợ hàn trong suốt, không halogen, đạt điện trở cách điện bề mặt cao</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Hợp kim</td><td>Sn96,5 Ag3,0 Cu0,5</td></tr><tr><td>Điểm nóng chảy</td><td>217–220 °C</td></tr><tr><td>Cỡ hạt</td><td>Type 4, 20–38 µm</td></tr><tr><td>Hàm lượng kim loại</td><td>88,5%</td></tr><tr><td>Độ nhớt (Malcom, 10 vòng/phút)</td><td>200 Pa·s</td></tr><tr><td>Nhiệt độ đỉnh reflow</td><td>235–250 °C</td></tr></table><h4>Lưu ý khi thi công</h4><p>Lấy kem ra khỏi tủ lạnh và để đạt nhiệt độ phòng trong hũ kín trước khi mở để tránh ngưng tụ hơi nước. Khuấy nhẹ 1–2 phút trước khi đưa lên stencil. Không trộn kem đã dùng trên stencil với kem mới trong hũ. Thiết lập profile reflow có thời gian trên nhiệt độ nóng chảy 40–90 giây, tốc độ gia nhiệt 1–3 °C/giây.</p><blockquote>Kiểm tra độ dày kem in bằng máy SPI sau mỗi lần đổi stencil giúp phát hiện sớm nguyên nhân lỗi thiếu thiếc, cầu hàn trước khi gắn linh kiện.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn cỡ hạt, profile reflow và chạy thử trên dây chuyền SMT của bạn.</p>','<p><strong>Fuji Chemical SMT Solder Paste</strong> is a lead-free SAC305 alloy solder paste that combines uniformly spherical solder powder with a new-generation no-clean flux system. It delivers consistent print quality over many hours on the stencil, good wetting on common surface finishes and safe flux residues that do not require post-solder cleaning.</p><h3>Typical Applications</h3><ul><li>Reflow soldering of 0201 and 0402 chip components and fine-pitch ICs</li><li>Soldering BGA, QFN and LGA packages on multilayer boards</li><li>Manufacturing consumer electronics, phones and wearables</li><li>Automotive control boards and industrial equipment</li><li>LED modules, power supplies and telecom equipment</li></ul><h3>Advantages</h3><ol><li>Stable printing for up to 8 hours on the stencil with minimal viscosity change</li><li>Good wetting on OSP, ENIG and immersion tin; minimal solder balling and bridging</li><li>Reduces voiding under QFN thermal pads</li><li>Clear, halogen-free flux residue with high surface insulation resistance</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Alloy</td><td>Sn96.5 Ag3.0 Cu0.5</td></tr><tr><td>Melting point</td><td>217–220 °C</td></tr><tr><td>Particle size</td><td>Type 4, 20–38 µm</td></tr><tr><td>Metal content</td><td>88.5%</td></tr><tr><td>Viscosity (Malcom, 10 rpm)</td><td>200 Pa·s</td></tr><tr><td>Peak reflow temperature</td><td>235–250 °C</td></tr></table><h4>Application Notes</h4><p>Remove the paste from the refrigerator and allow it to reach room temperature in the sealed jar before opening to prevent condensation. Stir gently for 1–2 minutes before placing it on the stencil. Do not mix used paste from the stencil with fresh paste in the jar. Set a reflow profile with 40–90 seconds time above liquidus and a ramp rate of 1–3 °C/second.</p><blockquote>Checking printed paste thickness with an SPI machine after every stencil change helps catch the causes of insufficient solder and bridging early, before components are placed.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on particle size and reflow profiles, and for trial runs on your SMT line.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Kem hàn SMT không chì</td></tr><tr><td>Thương hiệu</td><td>Fuji Chemical</td></tr><tr><td>Gốc hóa học</td><td>Hợp kim SAC305 + chất trợ hàn gốc nhựa thông biến tính</td></tr><tr><td>Màu sắc</td><td>Xám bạc</td></tr><tr><td>Số thành phần</td><td>1</td></tr><tr><td>Hợp kim</td><td>Sn96,5 Ag3,0 Cu0,5</td></tr><tr><td>Điểm nóng chảy</td><td>217–220 °C</td></tr><tr><td>Cỡ hạt</td><td>Type 4 (20–38 µm), có Type 3</td></tr><tr><td>Hàm lượng kim loại</td><td>88,5%</td></tr><tr><td>Độ nhớt</td><td>200 Pa·s (Malcom)</td></tr><tr><td>Phân loại chất trợ hàn</td><td>ROL0, no-clean, không halogen</td></tr><tr><td>Thời gian sống trên stencil</td><td>8 giờ</td></tr><tr><td>Nhiệt độ bảo quản</td><td>0–10 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH, IPC J-STD-004/005</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Lead-free SMT solder paste</td></tr><tr><td>Brand</td><td>Fuji Chemical</td></tr><tr><td>Chemistry</td><td>SAC305 alloy + modified rosin-based flux</td></tr><tr><td>Color</td><td>Silver gray</td></tr><tr><td>Components</td><td>1</td></tr><tr><td>Alloy</td><td>Sn96.5 Ag3.0 Cu0.5</td></tr><tr><td>Melting point</td><td>217–220 °C</td></tr><tr><td>Particle size</td><td>Type 4 (20–38 µm), Type 3 available</td></tr><tr><td>Metal content</td><td>88.5%</td></tr><tr><td>Viscosity</td><td>200 Pa·s (Malcom)</td></tr><tr><td>Flux classification</td><td>ROL0, no-clean, halogen-free</td></tr><tr><td>Stencil life</td><td>8 hours</td></tr><tr><td>Storage temperature</td><td>0–10 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH, IPC J-STD-004/005</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>In qua stencil để hàn reflow linh kiện dán bề mặt SMD, BGA, QFN trên bo mạch điện tử tiêu dùng, ô tô, viễn thông và công nghiệp</p><h4>Đặc tính</h4><p>Hợp kim SAC305 không chì / Nóng chảy 217–220 °C / Cỡ hạt Type 4 (20–38 µm) / Kim loại 88,5% / Trợ hàn no-clean ROL0</p><h4>Bảo quản</h4><p>Lạnh 0–10 °C, để về nhiệt độ phòng 2–4 giờ trước khi mở</p>','<h4>Applications</h4><p>Stencil printed for reflow soldering of SMD, BGA and QFN components on consumer, automotive, telecom and industrial circuit boards</p><h4>Properties</h4><p>Lead-free SAC305 alloy / Melting 217–220 °C / Type 4 powder (20–38 µm) / Metal content 88.5% / No-clean ROL0 flux</p><h4>Storage</h4><p>Refrigerate at 0–10 °C, warm up 2–4 hours before opening</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,28,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0),(520,NULL,1065,'uploads/images/ams/cat-2.jpg',NULL,'uploads/images/ams/cat-1.jpg','<p><strong>3M Băng keo dẫn nhiệt</strong> là băng keo hai mặt sử dụng keo acrylic độn hạt gốm, cho phép vừa dẫn nhiệt vừa liên kết cơ học giữa linh kiện và bộ tản nhiệt. Giải pháp này thay thế cùng lúc kẹp giữ, vít và mỡ tản nhiệt, giúp thiết kế mỏng gọn hơn và quy trình lắp ráp sạch, nhanh, không cần thời gian đóng rắn.</p><h3>Ứng dụng tiêu biểu</h3><ul><li>Dán tản nhiệt nhôm lên chip, bộ nhớ và chip cầu trên bo mạch</li><li>Dán dải LED lên thanh nhôm trong đèn tuýp, đèn panel</li><li>Cố định đèn nền và mô-đun LED màn hình lên khung kim loại</li><li>Truyền nhiệt giữa pin, bo mạch và vỏ trong thiết bị cầm tay</li><li>Dán cảm biến nhiệt, linh kiện công suất nhỏ lên vỏ máy</li></ul><h3>Ưu điểm</h3><ol><li>Vừa dẫn nhiệt vừa kết dính, không cần kẹp hay vít giữ</li><li>Thi công sạch, nhanh, không đóng rắn, không chảy tràn như keo lỏng</li><li>Cách điện, an toàn khi dán sát mạch in</li><li>Dễ bế theo hình dạng chi tiết, phù hợp lắp ráp tự động</li></ol><h3>Thông số chính</h3><table><tr><th>Chỉ tiêu</th><th>Giá trị</th></tr><tr><td>Độ dẫn nhiệt</td><td>0,6–1,0 W/m·K</td></tr><tr><td>Độ dày</td><td>0,13–0,5 mm</td></tr><tr><td>Trở kháng nhiệt</td><td>0,5–1,5 °C·cm²/W</td></tr><tr><td>Độ bám dính bóc 90° trên nhôm</td><td>12 N/25 mm</td></tr><tr><td>Điện áp đánh thủng</td><td>5 kV</td></tr></table><h4>Lưu ý khi thi công</h4><p>Bề mặt cần phẳng, sạch, không dầu mỡ; lau bằng cồn isopropyl và để khô. Miết hoặc ép đều với áp lực khoảng 100–200 kPa trong vài giây để loại bỏ bọt khí, vì khoảng trống không khí làm tăng mạnh trở nhiệt. Băng keo phù hợp khe hở nhỏ và bề mặt phẳng; với bề mặt cong vênh hoặc khe hở lớn nên chọn tấm đệm dẫn nhiệt mềm.</p><blockquote>Chọn băng keo mỏng nhất mà vẫn bù được độ phẳng bề mặt, vì trở nhiệt tăng gần như tỷ lệ thuận với chiều dày lớp keo.</blockquote><p>Liên hệ đội ngũ kỹ thuật <a href=\"lien-he\">AMS Việt Nam</a> để được tư vấn độ dày, gia công bế theo bản vẽ và nhận mẫu thử nhiệt.</p>','<p><strong>3M Thermally Conductive Tape</strong> is a double-sided tape using a ceramic-filled acrylic adhesive that provides both heat transfer and a mechanical bond between components and heat sinks. It replaces clips, screws and thermal grease all at once, enabling thinner, more compact designs and a clean, fast assembly process with no cure time.</p><h3>Typical Applications</h3><ul><li>Bonding aluminum heat sinks to chips, memory and chipsets on circuit boards</li><li>Bonding LED strips to aluminum bars in tube and panel lights</li><li>Securing backlights and display LED modules to metal frames</li><li>Heat transfer between batteries, circuit boards and housings in handheld devices</li><li>Bonding thermal sensors and small power components to equipment housings</li></ul><h3>Advantages</h3><ol><li>Conducts heat and bonds at the same time, with no clips or screws needed</li><li>Clean, fast application with no curing and no overflow like liquid adhesives</li><li>Electrically insulating, safe to apply close to printed circuits</li><li>Easy to die-cut to part shape, suitable for automated assembly</li></ol><h3>Key Specifications</h3><table><tr><th>Property</th><th>Value</th></tr><tr><td>Thermal conductivity</td><td>0.6–1.0 W/m·K</td></tr><tr><td>Thickness</td><td>0.13–0.5 mm</td></tr><tr><td>Thermal impedance</td><td>0.5–1.5 °C·cm²/W</td></tr><tr><td>90° peel adhesion on aluminum</td><td>12 N/25 mm</td></tr><tr><td>Breakdown voltage</td><td>5 kV</td></tr></table><h4>Application Notes</h4><p>Surfaces must be flat, clean and free of oil and grease; wipe with isopropyl alcohol and allow to dry. Press or roll down evenly at about 100–200 kPa for a few seconds to eliminate air bubbles, since air voids sharply increase thermal resistance. The tape is suited to small gaps and flat surfaces; for warped surfaces or large gaps, choose a soft thermal gap pad instead.</p><blockquote>Choose the thinnest tape that still compensates for surface flatness, since thermal resistance increases almost in direct proportion to adhesive thickness.</blockquote><p>Contact the technical team at <a href=\"lien-he\">AMS Vietnam</a> for advice on thickness, die-cutting to your drawings and samples for thermal testing.</p>','<table><tbody><tr><td>Loại sản phẩm</td><td>Băng keo hai mặt dẫn nhiệt</td></tr><tr><td>Thương hiệu</td><td>3M</td></tr><tr><td>Gốc hóa học</td><td>Keo acrylic độn hạt gốm</td></tr><tr><td>Màu sắc</td><td>Trắng, xám</td></tr><tr><td>Số thành phần</td><td>1 (dạng cuộn, tấm)</td></tr><tr><td>Độ dày</td><td>0,13–0,5 mm</td></tr><tr><td>Độ dẫn nhiệt</td><td>0,6–1,0 W/m·K</td></tr><tr><td>Trở kháng nhiệt</td><td>0,5–1,5 °C·cm²/W</td></tr><tr><td>Độ bám dính bóc 90°</td><td>12 N/25 mm trên nhôm</td></tr><tr><td>Độ bền cắt tĩnh</td><td>giữ 1 kg/6,45 cm² trong 10.000 phút ở 25 °C</td></tr><tr><td>Điện áp đánh thủng</td><td>5 kV</td></tr><tr><td>Nhiệt độ tối đa</td><td>120 °C dài hạn, 150 °C ngắn hạn</td></tr><tr><td>Nhiệt độ tối thiểu</td><td>-40 °C</td></tr><tr><td>Tiêu chuẩn</td><td>RoHS, REACH, UL 94 V-0</td></tr></tbody></table>','<table><tbody><tr><td>Product type</td><td>Thermally conductive double-sided tape</td></tr><tr><td>Brand</td><td>3M</td></tr><tr><td>Chemistry</td><td>Ceramic-filled acrylic adhesive</td></tr><tr><td>Color</td><td>White, gray</td></tr><tr><td>Components</td><td>1 (rolls, sheets)</td></tr><tr><td>Thickness</td><td>0.13–0.5 mm</td></tr><tr><td>Thermal conductivity</td><td>0.6–1.0 W/m·K</td></tr><tr><td>Thermal impedance</td><td>0.5–1.5 °C·cm²/W</td></tr><tr><td>90° peel adhesion</td><td>12 N/25 mm on aluminum</td></tr><tr><td>Static shear strength</td><td>holds 1 kg/6.45 cm² for 10,000 minutes at 25 °C</td></tr><tr><td>Breakdown voltage</td><td>5 kV</td></tr><tr><td>Maximum temperature</td><td>120 °C long-term, 150 °C short-term</td></tr><tr><td>Minimum temperature</td><td>-40 °C</td></tr><tr><td>Standards</td><td>RoHS, REACH, UL 94 V-0</td></tr></tbody></table>','<h4>Ứng dụng</h4><p>Dán tản nhiệt nhôm lên chip, bo mạch; dán dải LED và đèn nền màn hình lên khung kim loại; thay kẹp, vít trong thiết bị điện tử mỏng</p><h4>Đặc tính</h4><p>Dẫn nhiệt 0,6–1,0 W/m·K / Dày 0,13–0,5 mm / Bám dính bóc 90° 12 N/25 mm / Đánh thủng 5 kV / Làm việc -40 đến 120 °C</p><h4>Bảo quản</h4><p>15–25 °C, độ ẩm 40–60%, dùng trong 12 tháng</p>','<h4>Applications</h4><p>Bonds heat sinks to chips and boards; mounts LED strips and backlights to metal frames; replaces clips and screws</p><h4>Properties</h4><p>Conductivity 0.6–1.0 W/m·K / Thickness 0.13–0.5 mm / 90° peel 12 N/25 mm / Breakdown 5 kV / Service range -40 to 120 °C</p><h4>Storage</h4><p>15–25 °C, 40–60% RH, use within 12 months</p>',1,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,NULL,NULL,NULL,23,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,NULL,0,0,0,0,0);
