INSERT INTO `rates` VALUES (12,'Linh kiện ô tô','Automotive components',NULL,NULL,NULL,'“Đội kỹ thuật AMS khảo sát tận dây chuyền và đề xuất vật liệu thay thế giúp chúng tôi giảm đáng kể chi phí mà vẫn giữ nguyên chất lượng.”','“The AMS technical team surveyed our production line on site and proposed alternative materials that significantly reduced our costs while keeping the same quality.”',NULL,NULL,1,1,1,'Nguyễn Minh Tuấn','Nguyen Minh Tuan',NULL,'',NULL,'',NULL,1792059897,3,'Trưởng phòng Mua hàng','Purchasing Manager',NULL,NULL,NULL,'\'\\\'0\\\'\'',1),(13,'Điện tử','Electronics',NULL,NULL,NULL,'“Vật liệu tản nhiệt AMS cung cấp ổn định về chất lượng, giao hàng đúng hẹn, đội ngũ hỗ trợ kỹ thuật phản hồi rất nhanh khi chúng tôi cần.”','“The thermal materials supplied by AMS are consistent in quality and always delivered on time, and the technical support team responds very quickly whenever we need them.”',NULL,NULL,1,1,1,'Trần Thu Hà','Tran Thu Ha',NULL,'',NULL,'',NULL,1792059897,2,'Kỹ sư chất lượng','Quality Engineer',NULL,NULL,NULL,'\'\\\'0\\\'\'',1),(14,'Thiết bị y tế','Medical devices',NULL,NULL,NULL,'“Nhờ buổi tư vấn 1-1 của AMS, chúng tôi chọn được giải pháp băng keo phù hợp tiêu chuẩn y tế và rút ngắn thời gian phê duyệt vật liệu.”','“Thanks to the 1-on-1 consultation with AMS, we found a tape solution that meets medical standards and shortened our material approval time.”',NULL,NULL,1,1,1,'Lê Quang Long','Le Quang Long',NULL,'',NULL,'',NULL,1792059897,1,'Giám đốc sản xuất','Production Director',NULL,NULL,NULL,'\'\\\'0\\\'\'',1);
/*!40000 ALTER TABLE `rates` ENABLE KEYS */;
