INSERT INTO `settings` VALUES (2,'SEO description',NULL,'description','AMS cung cấp vật liệu và giải pháp kỹ thuật cho nhà máy: băng keo công nghiệp, vật liệu tản nhiệt, cách điện, mút xốp chống rung, phủ bảo vệ.',1,'textarea',1,160),(12,'Email nhận thông báo',NULL,'email','info@amsvn.net',1,'text',1,0),(57,'Site Name',NULL,'site_name','AMS Việt Nam',70,'text',1,0),(3,'SEO keyword',NULL,'keyword','Với hơn 10 năm kinh nghiệm và trải qua hàng ngàn dự án, chúng tôi tự hào không phải là doanh nghiệp cung cấp nhiều dịch vụ. Chúng tôi dành rất nhiều thời gian để tối ưu quy trình xây dựng website tốt nhất cho khách hàng, đảm bảo quản trị đơn giản nhất, chuẩn SEO nhất, tích hợp nhiều công cụ nhất.',1,'textarea',1,120),(41,'Theme Setting',NULL,'theme_setting','{\"s1\":{\"background\":\"\",\"background_2\":\"\",\"text\":\"\",\"link\":\"\",\"hover\":\"\"},\"s2\":{\"background\":\"\",\"background_2\":\"\",\"text\":\"\",\"link\":\"\",\"hover\":\"\"},\"s3\":{\"background\":\"\",\"background_2\":\"\",\"text\":\"\",\"link\":\"\",\"hover\":\"\"},\"s4\":{\"background\":\"\",\"background_2\":\"\",\"text\":\"\",\"link\":\"\",\"hover\":\"\"},\"s5\":{\"background\":\"\",\"background_2\":\"\",\"text\":\"\",\"link\":\"\",\"hover\":\"\"},\"s6\":{\"background\":\"\",\"background_2\":\"\",\"text\":\"\",\"link\":\"\",\"hover\":\"\"},\"s7\":{\"background\":\"\",\"background_2\":\"\",\"text\":\"\",\"link\":\"\",\"hover\":\"\"},\"s8\":{\"background\":\"\",\"background_2\":\"\",\"text\":\"\",\"link\":\"\",\"hover\":\"\"},\"s9\":{\"background\":\"\",\"background_2\":\"\",\"text\":\"\",\"link\":\"\",\"hover\":\"\"},\"s10\":{\"background\":\"\",\"background_2\":\"\",\"text\":\"\",\"link\":\"\",\"hover\":\"\"},\"s11\":{\"background\":\"\",\"background_2\":\"\",\"text\":\"\",\"link\":\"\",\"hover\":\"\"},\"s12\":{\"background\":\"\",\"background_2\":\"\",\"text\":\"\",\"link\":\"\",\"hover\":\"\"},\"s13\":{\"background\":\"\",\"background_2\":\"\",\"text\":\"\",\"link\":\"\",\"hover\":\"\"}}',1,'textar